:root {
  --orange: #ff7a18;
  --orange-hot: #ffb25e;
  --cyan: #69e2ff;
  --red: #ff3b30;
  --ink: #0b0d10;
  --steel: #aab4bf;
}

* { margin: 0; padding: 0; box-sizing: border-box; }

html, body {
  width: 100%;
  height: 100%;
  overflow: hidden;
  background: #05070a;
  color: #e9eef5;
  font-family: "Barlow Condensed", "Arial Narrow", "Roboto Condensed", system-ui, sans-serif;
  user-select: none;
  -webkit-user-select: none;
  cursor: default;
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.hidden { display: none !important; }

/* ------------------------------------------------------------------ HUD */
#hud {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 10;
  text-transform: uppercase;
  letter-spacing: 0.08em;
}

.vignette {
  position: absolute;
  inset: 0;
  background:
    radial-gradient(ellipse at center, transparent 46%, rgba(0, 0, 0, 0.38) 100%),
    linear-gradient(180deg, rgba(0, 0, 0, 0.35), transparent 18%, transparent 78%, rgba(0, 0, 0, 0.45));
  mix-blend-mode: multiply;
}

.grain {
  position: absolute;
  inset: 0;
  opacity: 0.16;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='0.5'/%3E%3C/svg%3E");
  animation: grain 0.6s steps(2) infinite;
}
@keyframes grain {
  0% { transform: translate(0, 0); }
  50% { transform: translate(-2%, 1%); }
  100% { transform: translate(1%, -2%); }
}

#topbar {
  position: absolute;
  top: 26px;
  left: 34px;
  right: 34px;
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
}

.brand { display: flex; align-items: center; gap: 13px; }
.logo {
  width: 46px;
  height: 46px;
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 20px;
  letter-spacing: -0.04em;
  color: #0b0d10;
  background: linear-gradient(145deg, var(--orange-hot), var(--orange));
  clip-path: polygon(0 0, 100% 0, 100% 74%, 76% 100%, 0 100%);
  box-shadow: 0 0 24px rgba(255, 122, 24, 0.45);
}
.brand-text h1 {
  font-size: 21px;
  font-weight: 800;
  letter-spacing: 0.2em;
  line-height: 1;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.8);
}
.brand-text p {
  margin-top: 5px;
  font-size: 9px;
  letter-spacing: 0.36em;
  color: var(--orange);
  opacity: 0.9;
}

.mission {
  display: flex;
  align-items: center;
  gap: 20px;
  padding: 10px 22px;
  background: linear-gradient(180deg, rgba(8, 11, 15, 0.72), rgba(8, 11, 15, 0.35));
  border-top: 1px solid rgba(255, 255, 255, 0.09);
  border-bottom: 1px solid rgba(255, 255, 255, 0.06);
  backdrop-filter: blur(7px);
  clip-path: polygon(12px 0, 100% 0, 100% 100%, 0 100%, 0 12px);
}
.mission .stat { display: flex; flex-direction: column; align-items: center; gap: 3px; }
.mission label { font-size: 8px; letter-spacing: 0.3em; color: #8593a3; }
.mission b {
  font-size: 19px;
  font-weight: 700;
  font-variant-numeric: tabular-nums;
  letter-spacing: 0.1em;
  color: #f2f6fa;
}
.mission .divider { width: 1px; height: 26px; background: rgba(255, 255, 255, 0.14); }

#banner {
  position: absolute;
  top: 116px;
  left: 50%;
  transform: translateX(-50%);
  text-align: center;
  opacity: 0;
  transition: opacity 0.5s ease;
}
#banner.show { opacity: 1; }
#banner h2 {
  font-size: 40px;
  font-weight: 800;
  letter-spacing: 0.28em;
  padding: 6px 0;
  color: #fff;
  text-shadow: 0 0 24px rgba(255, 122, 24, 0.55), 0 4px 30px rgba(0, 0, 0, 0.8);
}
#banner p { font-size: 11px; letter-spacing: 0.44em; color: var(--orange); }
.banner-line {
  width: 340px;
  height: 1px;
  margin: 8px auto;
  background: linear-gradient(90deg, transparent, rgba(255, 122, 24, 0.85), transparent);
}

#crosshair {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 44px;
  height: 44px;
  transform: translate(-50%, -50%);
  transition: opacity 0.15s;
}
#crosshair .ch {
  position: absolute;
  background: rgba(235, 245, 255, 0.92);
  box-shadow: 0 0 6px rgba(0, 0, 0, 0.9);
}
#crosshair .ch.t, #crosshair .ch.b { width: 2px; height: 9px; left: 21px; }
#crosshair .ch.l, #crosshair .ch.r { width: 9px; height: 2px; top: 21px; }
#crosshair .ch.t { top: 3px; }
#crosshair .ch.b { bottom: 3px; }
#crosshair .ch.l { left: 3px; }
#crosshair .ch.r { right: 3px; }
#crosshair .dot {
  width: 2px; height: 2px; left: 21px; top: 21px;
  background: var(--orange); box-shadow: 0 0 6px var(--orange);
}
#crosshair.ads .ch { opacity: 0.55; }

#hitmarker {
  position: absolute;
  left: 50%;
  top: 50%;
  width: 34px;
  height: 34px;
  transform: translate(-50%, -50%) rotate(45deg);
  opacity: 0;
}
#hitmarker span {
  position: absolute;
  width: 11px;
  height: 2px;
  background: #fff;
  box-shadow: 0 0 8px rgba(255, 255, 255, 0.9);
}
#hitmarker span:nth-child(1) { left: 0; top: 0; }
#hitmarker span:nth-child(2) { right: 0; top: 0; }
#hitmarker span:nth-child(3) { left: 0; bottom: 0; }
#hitmarker span:nth-child(4) { right: 0; bottom: 0; }
#hitmarker.show { animation: hit 0.22s ease-out; }
#hitmarker.kill span { background: var(--red); box-shadow: 0 0 10px var(--red); }
#hitmarker.head span { background: var(--orange-hot); box-shadow: 0 0 10px var(--orange); }
@keyframes hit {
  0% { opacity: 1; transform: translate(-50%, -50%) rotate(45deg) scale(1.25); }
  100% { opacity: 0; transform: translate(-50%, -50%) rotate(45deg) scale(1); }
}

#killfeed {
  position: absolute;
  top: 100px;
  right: 34px;
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 6px;
}
.kill-item {
  display: flex;
  align-items: center;
  gap: 9px;
  padding: 7px 12px;
  font-size: 10px;
  letter-spacing: 0.16em;
  color: #dfe8f2;
  background: linear-gradient(90deg, rgba(10, 13, 17, 0), rgba(10, 13, 17, 0.75));
  border-right: 2px solid var(--orange);
  animation: feedIn 0.25s ease-out;
}
.kill-item b { color: var(--orange); font-weight: 700; }
.kill-item .hs { color: var(--cyan); font-size: 8px; }
@keyframes feedIn {
  from { opacity: 0; transform: translateX(16px); }
  to { opacity: 1; transform: translateX(0); }
}

#vitals {
  position: absolute;
  left: 34px;
  bottom: 34px;
  width: 268px;
}
.vital-top {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  margin-bottom: 7px;
}
.vital-top .tag { font-size: 8px; letter-spacing: 0.3em; color: #8c9aa9; }
#healthnum {
  font-size: 26px;
  font-weight: 800;
  line-height: 1;
  color: #f3f8ff;
  font-variant-numeric: tabular-nums;
  text-shadow: 0 2px 12px rgba(0, 0, 0, 0.9);
}
#vitals .bar {
  height: 7px;
  background: rgba(10, 14, 19, 0.72);
  border: 1px solid rgba(255, 255, 255, 0.12);
  transform: skewX(-20deg);
  overflow: hidden;
}
#healthbar {
  height: 100%;
  width: 100%;
  background: linear-gradient(90deg, #ff7a18, #ffcf8a);
  box-shadow: 0 0 14px rgba(255, 122, 24, 0.6);
  transition: width 0.18s ease, background 0.3s;
}
#healthbar.low { background: linear-gradient(90deg, #ff2d20, #ff7a5e); box-shadow: 0 0 16px rgba(255, 59, 48, 0.8); }
.vital-bottom {
  display: flex;
  justify-content: space-between;
  margin-top: 6px;
  font-size: 7.5px;
  letter-spacing: 0.26em;
  color: #758392;
}
#status { color: var(--cyan); }

#ammo {
  position: absolute;
  right: 34px;
  bottom: 28px;
  text-align: right;
}
.weapon-name { font-size: 10px; letter-spacing: 0.32em; color: #94a2b2; }
.weapon-name em { color: var(--orange); font-style: normal; }
.ammo-line {
  display: flex;
  align-items: baseline;
  justify-content: flex-end;
  gap: 6px;
  margin: 2px 0 0;
  font-variant-numeric: tabular-nums;
}
#ammo-mag {
  font-size: 62px;
  font-weight: 800;
  line-height: 0.95;
  letter-spacing: -0.02em;
  color: #fff;
  text-shadow: 0 0 22px rgba(255, 255, 255, 0.15), 0 4px 18px rgba(0, 0, 0, 0.9);
}
.ammo-line .slash { font-size: 22px; color: #55616e; }
#ammo-reserve { font-size: 22px; font-weight: 600; color: #97a4b3; }
#ammo.empty #ammo-mag { color: var(--red); text-shadow: 0 0 20px rgba(255, 59, 48, 0.45); }
#reload-hint {
  margin-top: 3px;
  font-size: 8px;
  letter-spacing: 0.3em;
  color: var(--orange);
  opacity: 0;
  transition: opacity 0.2s;
}
#ammo.low #reload-hint, #ammo.empty #reload-hint { opacity: 1; }

#hint {
  position: absolute;
  left: 50%;
  bottom: 16px;
  transform: translateX(-50%);
  font-size: 8px;
  letter-spacing: 0.22em;
  color: rgba(180, 194, 209, 0.45);
  white-space: nowrap;
}
#fps {
  position: absolute;
  right: 34px;
  top: 96px;
  font-size: 8px;
  letter-spacing: 0.2em;
  color: rgba(150, 165, 180, 0.5);
  font-variant-numeric: tabular-nums;
}

/* ------------------------------------------------------------- overlays */
#damage, #flash {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 12;
  opacity: 0;
}
#damage {
  background: radial-gradient(ellipse at center, transparent 38%, rgba(255, 20, 10, 0.55) 100%);
  transition: opacity 0.12s;
}
#flash { background: #ffd9a8; mix-blend-mode: screen; }

.overlay {
  position: fixed;
  inset: 0;
  z-index: 30;
  display: grid;
  place-items: center;
  background: radial-gradient(ellipse at 50% 45%, rgba(8, 12, 18, 0.52), rgba(3, 4, 6, 0.94));
  backdrop-filter: blur(3px);
}

#menu .menu-bg {
  position: absolute;
  inset: 0;
  background:
    linear-gradient(120deg, rgba(255, 122, 24, 0.09), transparent 42%),
    repeating-linear-gradient(90deg, transparent 0 79px, rgba(255, 255, 255, 0.022) 79px 80px),
    repeating-linear-gradient(0deg, transparent 0 79px, rgba(255, 255, 255, 0.022) 79px 80px);
  mask-image: radial-gradient(ellipse at center, #000 20%, transparent 78%);
}

.menu-inner {
  position: relative;
  width: min(760px, 90vw);
  text-align: center;
  padding: 30px 20px;
}

.menu-kicker {
  font-size: 9px;
  letter-spacing: 0.5em;
  color: var(--orange);
  margin-bottom: 18px;
}
.menu-kicker.danger { color: var(--red); }

.title {
  font-size: clamp(64px, 11vw, 132px);
  font-weight: 900;
  line-height: 0.86;
  letter-spacing: 0.01em;
  background: linear-gradient(180deg, #ffffff 18%, #b8c4d2 58%, #6a7684 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  filter: drop-shadow(0 8px 34px rgba(0, 0, 0, 0.9));
}
.subtitle {
  margin-top: 10px;
  font-size: clamp(18px, 2.4vw, 27px);
  font-weight: 600;
  letter-spacing: 0.42em;
  color: #cfd9e5;
}
.subtitle span { color: var(--orange); text-shadow: 0 0 26px rgba(255, 122, 24, 0.45); }
.blurb {
  margin: 26px auto 0;
  max-width: 560px;
  font-size: 13px;
  line-height: 1.65;
  letter-spacing: 0.13em;
  color: #94a3b4;
  text-transform: none;
}

button {
  position: relative;
  margin-top: 34px;
  padding: 16px 54px;
  border: 1px solid rgba(255, 122, 24, 0.75);
  background: linear-gradient(180deg, rgba(255, 122, 24, 0.22), rgba(255, 122, 24, 0.06));
  color: #fff;
  font-family: inherit;
  text-transform: uppercase;
  cursor: pointer;
  clip-path: polygon(16px 0, 100% 0, 100% calc(100% - 16px), calc(100% - 16px) 100%, 0 100%, 0 16px);
  transition: background 0.2s, box-shadow 0.2s, transform 0.1s;
  pointer-events: auto;
}
button:hover {
  background: linear-gradient(180deg, rgba(255, 122, 24, 0.42), rgba(255, 122, 24, 0.12));
  box-shadow: 0 0 38px rgba(255, 122, 24, 0.28), inset 0 0 24px rgba(255, 122, 24, 0.14);
}
button:active { transform: translateY(1px); }
button span {
  display: block;
  font-size: 18px;
  font-weight: 800;
  letter-spacing: 0.34em;
}
button small {
  display: block;
  margin-top: 4px;
  font-size: 8px;
  letter-spacing: 0.28em;
  color: rgba(255, 190, 140, 0.8);
}

.controls {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 14px 26px;
  margin-top: 34px;
}
.controls div { display: flex; align-items: center; gap: 5px; font-size: 8px; letter-spacing: 0.2em; color: #8492a1; }
.controls span { margin-left: 5px; }
kbd {
  display: inline-grid;
  place-items: center;
  min-width: 22px;
  height: 20px;
  padding: 0 6px;
  font-family: inherit;
  font-size: 9px;
  color: #d7e0ea;
  background: rgba(255, 255, 255, 0.06);
  border: 1px solid rgba(255, 255, 255, 0.18);
  border-bottom-color: rgba(255, 255, 255, 0.28);
}

.menu-foot {
  margin-top: 26px;
  font-size: 8px;
  letter-spacing: 0.3em;
  color: rgba(140, 154, 169, 0.6);
}

.menu-inner.small { max-width: 560px; }
.final-stats {
  display: flex;
  justify-content: center;
  gap: 46px;
  margin-top: 34px;
}
.final-stats div { display: flex; flex-direction: column; gap: 7px; }
.final-stats label { font-size: 8px; letter-spacing: 0.24em; color: #8492a1; }
.final-stats b { font-size: 32px; font-weight: 800; color: #fff; font-variant-numeric: tabular-nums; }

#loading {
  position: fixed;
  inset: 0;
  z-index: 50;
  display: grid;
  place-items: center;
  background: #05070a;
  transition: opacity 0.5s ease;
}
#loading.done { opacity: 0; pointer-events: none; }
.load-inner { text-align: center; }
.load-logo {
  width: 64px;
  height: 64px;
  margin: 0 auto 22px;
  display: grid;
  place-items: center;
  font-weight: 900;
  font-size: 26px;
  color: #0b0d10;
  background: linear-gradient(145deg, var(--orange-hot), var(--orange));
  clip-path: polygon(0 0, 100% 0, 100% 74%, 76% 100%, 0 100%);
}
.load-bar { width: 220px; height: 2px; background: rgba(255, 255, 255, 0.12); overflow: hidden; }
.load-bar i { display: block; width: 40%; height: 100%; background: var(--orange); animation: load 1s ease-in-out infinite; }
.load-text { margin-top: 12px; font-size: 8px; letter-spacing: 0.4em; color: #7d8a99; }
@keyframes load {
  0% { transform: translateX(-110%); }
  100% { transform: translateX(320%); }
}

@media (max-width: 860px) {
  #topbar { left: 16px; right: 16px; top: 16px; }
  .brand-text h1 { font-size: 15px; }
  .mission { gap: 12px; padding: 8px 14px; }
  .mission b { font-size: 14px; }
  .mission label { font-size: 6px; }
  #killfeed { right: 16px; top: 80px; }
  #vitals { left: 16px; bottom: 22px; width: 210px; }
  #ammo { right: 16px; bottom: 18px; }
  #ammo-mag { font-size: 44px; }
  #hint, #fps { display: none; }
  .blurb { font-size: 11px; }
}

import * as THREE from 'three';

/* ------------------------------------------------------------------ utils */
function mulberry32(a) {
  return function () {
    a |= 0; a = (a + 0x6d2b79f5) | 0;
    let t = Math.imul(a ^ (a >>> 15), 1 | a);
    t = (t + Math.imul(t ^ (t >>> 7), 61 | t)) ^ t;
    return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
  };
}

function canvas(size) {
  const c = document.createElement('canvas');
  c.width = size; c.height = size;
  return c;
}

function tex(c, srgb = true, repeat = [1, 1]) {
  const t = new THREE.CanvasTexture(c);
  t.wrapS = t.wrapT = THREE.RepeatWrapping;
  t.repeat.set(repeat[0], repeat[1]);
  t.colorSpace = srgb ? THREE.SRGBColorSpace : THREE.NoColorSpace;
  t.anisotropy = 8;
  return t;
}

function normalFromHeight(height, size, strength = 2.4) {
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(size, size);
  const d = img.data;
  const at = (x, y) => height[((y + size) % size) * size + ((x + size) % size)];
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const dx = (at(x + 1, y) - at(x - 1, y)) * strength;
      const dy = (at(x, y + 1) - at(x, y - 1)) * strength;
      const len = Math.hypot(dx, dy, 1);
      const i = (y * size + x) * 4;
      d[i] = ((-dx / len) * 0.5 + 0.5) * 255;
      d[i + 1] = ((dy / len) * 0.5 + 0.5) * 255;
      d[i + 2] = ((1 / len) * 0.5 + 0.5) * 255;
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return tex(c, false);
}

function grayTexture(fn, size = 256, repeat = [1, 1]) {
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const img = ctx.createImageData(size, size);
  const d = img.data;
  for (let y = 0; y < size; y++) {
    for (let x = 0; x < size; x++) {
      const v = Math.max(0, Math.min(1, fn(x / size, y / size)));
      const i = (y * size + x) * 4;
      d[i] = d[i + 1] = d[i + 2] = v * 255;
      d[i + 3] = 255;
    }
  }
  ctx.putImageData(img, 0, 0);
  return tex(c, false, repeat);
}

/* --------------------------------------------------------------- textures */
function concreteMaterial(seed = 7) {
  const size = 512;
  const rand = mulberry32(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#7b7f82';
  ctx.fillRect(0, 0, size, size);

  const img = ctx.getImageData(0, 0, size, size);
  const d = img.data;
  const height = new Float32Array(size * size);
  for (let i = 0; i < size * size; i++) {
    const n = (rand() - 0.5) * 26;
    d[i * 4] = Math.max(0, Math.min(255, d[i * 4] + n));
    d[i * 4 + 1] = Math.max(0, Math.min(255, d[i * 4 + 1] + n));
    d[i * 4 + 2] = Math.max(0, Math.min(255, d[i * 4 + 2] + n));
    height[i] = 0.5 + (rand() - 0.5) * 0.1 + (rand() > 0.985 ? 0.12 : 0);
  }
  ctx.putImageData(img, 0, 0);

  // stains and damp patches
  for (let i = 0; i < 14; i++) {
    const x = rand() * size, y = rand() * size, r = 18 + rand() * 74;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, `rgba(20,24,26,${0.1 + rand() * 0.16})`);
    g.addColorStop(0.7, 'rgba(20,24,26,0.05)');
    g.addColorStop(1, 'rgba(20,24,26,0)');
    ctx.fillStyle = g;
    ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }

  // expansion seams
  ctx.strokeStyle = 'rgba(28,30,32,0.6)';
  ctx.lineWidth = 3;
  for (const p of [0, 256]) {
    ctx.beginPath(); ctx.moveTo(p, 0); ctx.lineTo(p, size); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, p); ctx.lineTo(size, p); ctx.stroke();
  }
  ctx.strokeStyle = 'rgba(178,184,188,0.18)';
  ctx.lineWidth = 1;
  for (const p of [3, 259]) {
    ctx.beginPath(); ctx.moveTo(p, 0); ctx.lineTo(p, size); ctx.stroke();
    ctx.beginPath(); ctx.moveTo(0, p); ctx.lineTo(size, p); ctx.stroke();
  }

  // cracks
  ctx.strokeStyle = 'rgba(26,28,30,0.7)';
  for (let i = 0; i < 10; i++) {
    let x = rand() * size, y = rand() * size;
    ctx.lineWidth = 0.6 + rand() * 1.2;
    ctx.beginPath(); ctx.moveTo(x, y);
    const segs = 6 + Math.floor(rand() * 10);
    for (let s = 0; s < segs; s++) {
      x += (rand() - 0.5) * 34;
      y += (rand() - 0.5) * 34;
      ctx.lineTo(x, y);
    }
    ctx.stroke();
  }

  const map = tex(c, true, [8, 8]);
  const normalMap = normalFromHeight(height, size, 2.6);
  normalMap.repeat.set(8, 8);
  const roughnessMap = grayTexture((u, v) => 0.72 + Math.sin(u * 40 + v * 33) * 0.04 + rand() * 0.12, 256, [8, 8]);
  return new THREE.MeshStandardMaterial({ map, normalMap, roughnessMap, roughness: 1, metalness: 0.02, color: 0xffffff });
}

function metalMaterial(seed = 3, repeat = [2, 2]) {
  const size = 512;
  const rand = mulberry32(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#454c54';
  ctx.fillRect(0, 0, size, size);
  for (let i = 0; i < 2600; i++) {
    const y = rand() * size;
    const l = rand() * size;
    ctx.strokeStyle = `rgba(${190 + rand() * 50},${200 + rand() * 40},${210 + rand() * 40},${rand() * 0.05})`;
    ctx.lineWidth = 0.5 + rand();
    ctx.beginPath(); ctx.moveTo(rand() * size, y); ctx.lineTo(rand() * size + l, y); ctx.stroke();
  }
  for (let i = 0; i < 22; i++) {
    const x = rand() * size, y = rand() * size, r = 2 + rand() * 4;
    ctx.fillStyle = `rgba(20,22,25,${0.2 + rand() * 0.3})`;
    ctx.beginPath(); ctx.arc(x, y, r, 0, Math.PI * 2); ctx.fill();
    ctx.fillStyle = 'rgba(200,210,220,0.15)';
    ctx.beginPath(); ctx.arc(x - r * 0.25, y - r * 0.25, r * 0.45, 0, Math.PI * 2); ctx.fill();
  }
  // rust
  for (let i = 0; i < 9; i++) {
    const x = rand() * size, y = rand() * size, r = 8 + rand() * 30;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(120,62,28,0.3)');
    g.addColorStop(1, 'rgba(120,62,28,0)');
    ctx.fillStyle = g; ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }
  const map = tex(c, true, repeat);
  const roughnessMap = grayTexture((u, v) => 0.42 + Math.sin(u * 120) * 0.05 + rand() * 0.2, 256, repeat);
  return new THREE.MeshStandardMaterial({ map, roughnessMap, roughness: 1, metalness: 0.82, color: 0xffffff });
}

function containerMaterial(hex, code, seed = 11) {
  const size = 512;
  const rand = mulberry32(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  const base = new THREE.Color(hex);
  ctx.fillStyle = `#${base.getHexString()}`;
  ctx.fillRect(0, 0, size, size);

  // corrugated vertical ribs
  for (let x = 0; x < size; x += 16) {
    const g = ctx.createLinearGradient(x, 0, x + 16, 0);
    g.addColorStop(0, 'rgba(0,0,0,0.22)');
    g.addColorStop(0.35, 'rgba(255,255,255,0.12)');
    g.addColorStop(0.65, 'rgba(0,0,0,0.06)');
    g.addColorStop(1, 'rgba(0,0,0,0.26)');
    ctx.fillStyle = g;
    ctx.fillRect(x, 0, 16, size);
  }
  // frame rails
  ctx.fillStyle = 'rgba(0,0,0,0.4)';
  ctx.fillRect(0, 0, size, 16); ctx.fillRect(0, size - 16, size, 16);
  ctx.fillRect(0, 0, 18, size); ctx.fillRect(size - 18, 0, 18, size);

  // grime + rust drips
  for (let i = 0; i < 90; i++) {
    const x = rand() * size, w = 1 + rand() * 5, h = 20 + rand() * 180, y = rand() * size * 0.7;
    ctx.fillStyle = `rgba(${40 + rand() * 40},${24 + rand() * 20},${12 + rand() * 14},${0.05 + rand() * 0.16})`;
    ctx.fillRect(x, y, w, h);
  }
  for (let i = 0; i < 6; i++) {
    const x = rand() * size, y = rand() * size, r = 20 + rand() * 60;
    const g = ctx.createRadialGradient(x, y, 0, x, y, r);
    g.addColorStop(0, 'rgba(110,62,30,0.24)');
    g.addColorStop(1, 'rgba(110,62,30,0)');
    ctx.fillStyle = g; ctx.fillRect(x - r, y - r, r * 2, r * 2);
  }

  // stencil
  ctx.save();
  ctx.translate(70, size * 0.5);
  ctx.fillStyle = 'rgba(235,235,230,0.72)';
  ctx.font = 'bold 58px monospace';
  ctx.fillText(code, 0, 0);
  ctx.font = 'bold 20px monospace';
  ctx.fillStyle = 'rgba(235,235,230,0.5)';
  ctx.fillText('DGSU // MAX GROSS 30480 KG', 0, 34);
  ctx.fillText('SEAL INTACT — DO NOT OPEN', 0, 62);
  ctx.restore();

  const map = tex(c, true, [1, 1]);
  const roughnessMap = grayTexture((u, v) => 0.55 + Math.sin(u * 80) * 0.05 + rand() * 0.16, 256, [1, 1]);
  return new THREE.MeshStandardMaterial({ map, roughnessMap, roughness: 1, metalness: 0.55, color: 0xffffff });
}

function crateMaterial(seed = 5) {
  const size = 256;
  const rand = mulberry32(seed);
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#6d5537';
  ctx.fillRect(0, 0, size, size);
  for (let y = 0; y < size; y += 32) {
    ctx.fillStyle = `rgba(${95 + rand() * 30},${72 + rand() * 20},${44 + rand() * 14},0.8)`;
    ctx.fillRect(0, y + 1, size, 30);
    for (let i = 0; i < 26; i++) {
      ctx.strokeStyle = `rgba(42,30,18,${0.05 + rand() * 0.12})`;
      ctx.lineWidth = 0.7;
      ctx.beginPath();
      const yy = y + rand() * 30;
      ctx.moveTo(0, yy);
      ctx.bezierCurveTo(size * 0.3, yy + (rand() - 0.5) * 6, size * 0.7, yy + (rand() - 0.5) * 6, size, yy);
      ctx.stroke();
    }
    ctx.fillStyle = 'rgba(28,20,12,0.55)';
    ctx.fillRect(0, y + 30, size, 2);
  }
  ctx.strokeStyle = 'rgba(60,64,68,0.9)';
  ctx.lineWidth = 8;
  ctx.strokeRect(4, 4, size - 8, size - 8);
  ctx.fillStyle = 'rgba(220,210,190,0.35)';
  ctx.font = 'bold 20px monospace';
  ctx.fillText('DG // 7.62', 22, size * 0.5);
  const map = tex(c, true, [1, 1]);
  return new THREE.MeshStandardMaterial({ map, roughness: 0.85, metalness: 0.05 });
}

function stripeMaterial() {
  const size = 256;
  const c = canvas(size);
  const ctx = c.getContext('2d');
  ctx.fillStyle = '#c9922b';
  ctx.fillRect(0, 0, size, size);
  ctx.fillStyle = '#17191c';
  for (let i = -size; i < size * 2; i += 64) {
    ctx.save();
    ctx.translate(i, 0);
    ctx.rotate(-Math.PI / 4);
    ctx.fillRect(0, -size, 32, size * 3);
    ctx.restore();
  }
  // wear
  const rand = mulberry32(19);
  for (let i = 0; i < 300; i++) {
    ctx.fillStyle = `rgba(60,54,44,${rand() * 0.4})`;
    ctx.fillRect(rand() * size, rand() * size, 1 + rand() * 6, 1 + rand() * 3);
  }
  return new THREE.MeshStandardMaterial({ map: tex(c, true, [1, 1]), roughness: 0.8, metalness: 0.1 });
}

function windowTexture(seed = 4) {
  const s = 256;
  const c = canvas(s);
  const ctx = c.getContext('2d');
  const rand = mulberry32(seed);
  ctx.fillStyle = '#15181c';
  ctx.fillRect(0, 0, s, s);
  for (let y = 12; y < s; y += 32) {
    for (let x = 10; x < s; x += 28) {
      const lit = rand() > 0.38;
      ctx.fillStyle = lit
        ? `rgba(${230 + rand() * 20},${175 + rand() * 45},${110 + rand() * 50},${0.55 + rand() * 0.45})`
        : 'rgba(18,22,27,0.9)';
      ctx.fillRect(x, y, 18, 18);
      if (lit) {
        ctx.fillStyle = 'rgba(255,205,140,0.12)';
        ctx.fillRect(x - 3, y - 3, 24, 24);
      }
    }
  }
  return tex(c, true, [1, 1]);
}

/* ------------------------------------------------------------------- sky */
const SKY_FRAG = /* glsl */ `
  varying vec3 vWorld;
  uniform vec3 uSun;
  void main() {
    vec3 dir = normalize(vWorld);
    float h = dir.y;
    vec3 zenith = vec3(0.020, 0.038, 0.095);
    vec3 mid = vec3(0.135, 0.155, 0.235);
    vec3 horizon = vec3(0.95, 0.47, 0.24);
    vec3 ground = vec3(0.020, 0.022, 0.028);

    vec3 col = mix(horizon, mid, smoothstep(0.0, 0.18, h));
    col = mix(col, zenith, smoothstep(0.18, 0.75, h));
    col = mix(ground, col, smoothstep(-0.09, 0.015, h));

    float sd = max(dot(dir, normalize(uSun)), 0.0);
    col += vec3(1.0, 0.62, 0.30) * pow(sd, 220.0) * 3.2;
    col += vec3(1.0, 0.45, 0.18) * pow(sd, 15.0) * 0.38;
    col += vec3(0.85, 0.42, 0.22) * pow(sd, 3.0) * 0.08;

    // thin drifting cloud bands
    float band = smoothstep(0.62, 0.0, abs(h - 0.16)) * 0.5;
    float stripes = 0.5 + 0.5 * sin(dir.x * 14.0 + dir.z * 9.0 + dir.y * 30.0);
    col += vec3(0.20, 0.13, 0.13) * band * stripes * 0.35;

    // stars
    float star = step(0.9993, fract(sin(dot(dir, vec3(12.9898, 78.233, 45.164))) * 43758.5453));
    col += vec3(0.65, 0.75, 1.0) * star * smoothstep(0.25, 0.6, h) * 0.5;

    gl_FragColor = vec4(col, 1.0);
  }
`;

function makeSky(sunDir) {
  const geo = new THREE.SphereGeometry(260, 48, 24);
  const mat = new THREE.ShaderMaterial({
    vertexShader: /* glsl */ `
      varying vec3 vWorld;
      void main() {
        vWorld = (modelMatrix * vec4(position, 1.0)).xyz;
        gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
      }
    `,
    fragmentShader: SKY_FRAG,
    uniforms: { uSun: { value: sunDir.clone() } },
    side: THREE.BackSide,
    depthWrite: false,
    fog: false,
  });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.frustumCulled = false;
  mesh.renderOrder = -10;
  return mesh;
}

/* ----------------------------------------------------------------- world */
export function createWorld(renderer, scene) {
  const colliders = [];
  const raycastMeshes = [];
  const spawnPoints = [];
  const lamps = [];

  const concrete = concreteMaterial(7);
  const concrete2 = concreteMaterial(23);
  const steel = metalMaterial(3, [3, 1]);
  const containerRed = containerMaterial(0x8e3428, 'DGSU 402191', 2);
  const containerBlue = containerMaterial(0x24486b, 'DGSU 771044', 3);
  const containerGreen = containerMaterial(0x35553a, 'DGSU 118230', 4);
  const containerTan = containerMaterial(0x86693c, 'DGSU 905512', 5);
  const crateMat = crateMaterial(9);
  const stripeMat = stripeMaterial();
  const windows = windowTexture(4);
  const windows2 = windowTexture(8);
  const windowMat = new THREE.MeshStandardMaterial({
    map: windows, emissiveMap: windows, emissive: 0xffc07a, emissiveIntensity: 1.7, roughness: 0.65, metalness: 0.2,
  });
  const windowMat2 = new THREE.MeshStandardMaterial({
    map: windows2, emissiveMap: windows2, emissive: 0x8fd7ff, emissiveIntensity: 1.2, roughness: 0.65, metalness: 0.2,
  });

  const sunDir = new THREE.Vector3(0.55, 0.22, -0.8).normalize();

  // sky + environment
  const sky = makeSky(sunDir);
  scene.add(sky);
  try {
    const pmrem = new THREE.PMREMGenerator(renderer);
    const envScene = new THREE.Scene();
    const envSky = makeSky(sunDir);
    envSky.scale.setScalar(0.2);
    envScene.add(envSky);
    const ground = new THREE.Mesh(
      new THREE.CircleGeometry(40, 32),
      new THREE.MeshBasicMaterial({ color: 0x1b1a1c })
    );
    ground.rotation.x = -Math.PI / 2;
    ground.position.y = -2;
    envScene.add(ground);
    scene.environment = pmrem.fromScene(envScene, 0.03).texture;
    scene.environmentIntensity = 0.6;
    pmrem.dispose();
  } catch (e) { /* env map is optional */ }

  scene.fog = new THREE.FogExp2(0x2c2a30, 0.0135);

  // ---------------------------------------------------------------- lights
  const sun = new THREE.DirectionalLight(0xffb37a, 2.7);
  sun.position.copy(sunDir).multiplyScalar(60);
  sun.target.position.set(0, 0, 0);
  sun.castShadow = true;
  sun.shadow.mapSize.set(2048, 2048);
  sun.shadow.camera.left = -42;
  sun.shadow.camera.right = 42;
  sun.shadow.camera.top = 42;
  sun.shadow.camera.bottom = -42;
  sun.shadow.camera.near = 1;
  sun.shadow.camera.far = 140;
  sun.shadow.bias = -0.0004;
  sun.shadow.normalBias = 0.03;
  scene.add(sun, sun.target);

  const hemi = new THREE.HemisphereLight(0x8ba7d0, 0x2a2118, 0.85);
  scene.add(hemi);
  const fill = new THREE.DirectionalLight(0x6d9fd8, 0.5);
  fill.position.set(-25, 18, 30);
  scene.add(fill);

  // ----------------------------------------------------------------- ground
  const groundGeo = new THREE.PlaneGeometry(92, 92, 1, 1);
  const groundMat = concrete;
  const ground = new THREE.Mesh(groundGeo, groundMat);
  ground.rotation.x = -Math.PI / 2;
  ground.receiveShadow = true;
  scene.add(ground);
  raycastMeshes.push(ground);

  const apronMat = new THREE.MeshStandardMaterial({ color: 0x5e6164, roughness: 0.92, metalness: 0.03 });
  const apron = new THREE.Mesh(new THREE.PlaneGeometry(58, 58), apronMat);
  apron.rotation.x = -Math.PI / 2;
  apron.position.y = 0.004;
  apron.receiveShadow = true;
  scene.add(apron);
  raycastMeshes.push(apron);

  // paint markings
  const paintMat = new THREE.MeshStandardMaterial({
    color: 0xd9a53c, roughness: 0.8, metalness: 0.05,
    polygonOffset: true, polygonOffsetFactor: -2,
  });
  const addStripe = (x, z, w, d, rot = 0) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, d), paintMat);
    m.rotation.x = -Math.PI / 2;
    m.rotation.z = rot;
    m.position.set(x, 0.012, z);
    m.receiveShadow = true;
    scene.add(m);
  };
  addStripe(0, -8, 0.32, 34);
  addStripe(0, 8, 0.32, 34);
  addStripe(-8, 0, 34, 0.32);
  addStripe(8, 0, 34, 0.32);
  addStripe(-8, -8, 2, 2, Math.PI / 4);

  // hazard pads
  const hazard = (x, z, w, d) => {
    const m = new THREE.Mesh(new THREE.PlaneGeometry(w, d), stripeMat);
    m.rotation.x = -Math.PI / 2;
    m.position.set(x, 0.014, z);
    scene.add(m);
  };
  hazard(0, -20, 16, 1.4);
  hazard(-22, 0, 1.4, 14);
  hazard(20, 22, 10, 1.2);

  // puddles
  const puddleMat = new THREE.MeshStandardMaterial({
    color: 0x0d1014, metalness: 0.95, roughness: 0.06, transparent: true, opacity: 0.88,
    polygonOffset: true, polygonOffsetFactor: -3,
  });
  const rand = mulberry32(77);
  for (let i = 0; i < 9; i++) {
    const p = new THREE.Mesh(new THREE.CircleGeometry(1, 22), puddleMat);
    p.rotation.x = -Math.PI / 2;
    p.scale.set(1.5 + rand() * 2.8, 1 + rand() * 1.4, 1);
    p.position.set((rand() - 0.5) * 46, 0.018, (rand() - 0.5) * 46);
    scene.add(p);
  }

  // --------------------------------------------------------------- helpers
  const world = new THREE.Group();
  scene.add(world);
  world.updateMatrixWorld(true);

  function solid(mesh, collide = true) {
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    world.add(mesh);
    raycastMeshes.push(mesh);
    if (collide) {
      world.updateMatrixWorld(true);
      colliders.push(new THREE.Box3().setFromObject(mesh));
    }
    return mesh;
  }

  function box(w, h, d, mat, x, y, z, rotY = 0, collide = true) {
    const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat);
    m.position.set(x, y, z);
    m.rotation.y = rotY;
    return solid(m, collide);
  }

  // ------------------------------------------------------------- perimeter
  const wallH = 7;
  const trimMat = new THREE.MeshStandardMaterial({ color: 0x2a2d31, roughness: 0.6, metalness: 0.5 });
  const walls = [
    [72, wallH, 1, 0, wallH / 2, -34],
    [72, wallH, 1, 0, wallH / 2, 34],
    [1, wallH, 72, -34, wallH / 2, 0],
    [1, wallH, 72, 34, wallH / 2, 0],
  ];
  for (const [w, h, d, x, y, z] of walls) {
    box(w, h, d, concrete2, x, y, z);
    // top trim
    box(w + 0.4, 0.35, d + 0.4, trimMat, x, h + 0.16, z, 0, false);
  }
  // buttresses
  for (let i = -30; i <= 30; i += 10) {
    box(0.9, wallH - 0.5, 1.6, concrete2, i, wallH / 2, -34.6, 0, false);
    box(0.9, wallH - 0.5, 1.6, concrete2, i, wallH / 2, 34.6, 0, false);
