    const bulb = new THREE.Mesh(new THREE.PlaneGeometry(1.2, 0.36), lampMat);
    bulb.position.set(0, -0.16, 0.36);
    bulb.rotation.x = Math.PI / 2.5;
    head.add(bulb);
    const pl = new THREE.PointLight(0xffb067, 90, 34, 2);
    pl.position.set(x, 9.0, z);
    scene.add(pl);
    lamps.push({ light: pl, base: 90, phase: rand() * 10, kind: 'tower' });
  }

  // ------------------------------------------------------------- distant city
  const cityMat = new THREE.MeshStandardMaterial({ color: 0x1b2028, roughness: 0.9, metalness: 0.1 });
  for (let i = 0; i < 26; i++) {
    const a = (i / 26) * Math.PI * 2 + rand() * 0.12;
    const r = 55 + rand() * 30;
    const w = 5 + rand() * 9, h = 8 + rand() * 22, d = 5 + rand() * 9;
    const b = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), cityMat);
    b.position.set(Math.cos(a) * r, h / 2 - 2, Math.sin(a) * r);
    b.rotation.y = rand() * Math.PI;
    scene.add(b);
    if (rand() > 0.4) {
      const wm = new THREE.Mesh(new THREE.PlaneGeometry(w * 0.8, h * 0.7), rand() > 0.5 ? windowMat : windowMat2);
      wm.position.set(b.position.x + Math.sin(b.rotation.y) * 0, b.position.y, b.position.z);
      wm.lookAt(0, b.position.y, 0);
      scene.add(wm);
    }
  }

  // ------------------------------------------------------------- dust motes
  const dustCount = 380;
  const dustGeo = new THREE.BufferGeometry();
  const dustPos = new Float32Array(dustCount * 3);
  for (let i = 0; i < dustCount; i++) {
    dustPos[i * 3] = (rand() - 0.5) * 62;
    dustPos[i * 3 + 1] = rand() * 9;
    dustPos[i * 3 + 2] = (rand() - 0.5) * 62;
  }
  dustGeo.setAttribute('position', new THREE.BufferAttribute(dustPos, 3));
  const dustMat = new THREE.PointsMaterial({
    color: 0xffc38a, size: 0.045, transparent: true, opacity: 0.5,
    depthWrite: false, blending: THREE.AdditiveBlending, sizeAttenuation: true,
  });
  const dust = new THREE.Points(dustGeo, dustMat);
  scene.add(dust);

  // ------------------------------------------------------------- spawn points
  const spawns = [
    [0, -27], [-24, -22], [24, -20], [-27, 8], [27, 6], [-20, 27], [18, 27], [0, 28], [-25, -4], [26, -10],
  ];
  for (const [x, z] of spawns) spawnPoints.push(new THREE.Vector3(x, 0, z));

  const time0 = performance.now();

  function update(dt, t) {
    // lamp flicker
    for (const l of lamps) {
      if (l.kind === 'tower') {
        const n = Math.sin(t * 17 + l.phase) * 0.5 + Math.sin(t * 5.3 + l.phase * 2) * 0.5;
        l.light.intensity = l.base * (0.94 + n * 0.06);
      } else if (l.kind === 'beacon') {
        const on = Math.sin(t * 3.2) > 0.2;
        l.mesh.material.color.setHex(on ? 0xff3b20 : 0x3a0f08);
      }
    }
    // drifting dust
    const p = dust.geometry.attributes.position;
    for (let i = 0; i < dustCount; i += 3) {
      p.array[i * 3 + 1] += dt * (0.06 + (i % 5) * 0.01);
      p.array[i * 3] += dt * 0.04 * Math.sin(t * 0.4 + i);
      if (p.array[i * 3 + 1] > 9) p.array[i * 3 + 1] = 0;
    }
    p.needsUpdate = true;
    sky.position.copy(cameraRef());
  }

  // keep sky centered on camera
  let cam = null;
  function cameraRef() { return cam ? cam.position : new THREE.Vector3(); }
  function attachCamera(camera) { cam = camera; }

  return {
    colliders, raycastMeshes, spawnPoints, lamps, sunDir, sun,
    attachCamera, update,
    elapsed: () => (performance.now() - time0) / 1000,
  };
}

import * as THREE from 'three';

/* Procedural texture helpers for effects */
function radialTexture(size, inner, outer, spikes = 0) {
  const c = document.createElement('canvas');
  c.width = c.height = size;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, inner);
  g.addColorStop(0.25, outer);
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  if (spikes) {
    ctx.save();
    ctx.translate(size / 2, size / 2);
    ctx.globalCompositeOperation = 'lighter';
    for (let i = 0; i < spikes; i++) {
      ctx.rotate((Math.PI * 2) / spikes);
      const lg = ctx.createLinearGradient(0, 0, size / 2, 0);
      lg.addColorStop(0, inner);
      lg.addColorStop(1, 'rgba(0,0,0,0)');
      ctx.fillStyle = lg;
      ctx.beginPath();
      ctx.moveTo(0, -3);
      ctx.lineTo(size / 2, 0);
      ctx.lineTo(0, 3);
      ctx.closePath();
      ctx.fill();
    }
    ctx.restore();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

function scorchTexture() {
  const s = 128;
  const c = document.createElement('canvas');
  c.width = c.height = s;
  const ctx = c.getContext('2d');
  const g = ctx.createRadialGradient(s / 2, s / 2, 2, s / 2, s / 2, s / 2);
  g.addColorStop(0, 'rgba(6,6,7,0.95)');
  g.addColorStop(0.35, 'rgba(12,11,10,0.75)');
  g.addColorStop(0.72, 'rgba(20,18,16,0.25)');
  g.addColorStop(1, 'rgba(0,0,0,0)');
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, s, s);
  // chipped edges
  ctx.globalCompositeOperation = 'destination-out';
  for (let i = 0; i < 40; i++) {
    const a = Math.random() * Math.PI * 2;
    const r = 26 + Math.random() * 34;
    ctx.beginPath();
    ctx.arc(64 + Math.cos(a) * r, 64 + Math.sin(a) * r, 1 + Math.random() * 5, 0, Math.PI * 2);
    ctx.fill();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export class FX {
  constructor(scene) {
    this.scene = scene;
    this.cursor = 0;
    this.N = 900;

    const geo = new THREE.BufferGeometry();
    this.pos = new Float32Array(this.N * 3);
    this.vel = new Float32Array(this.N * 3);
    this.col = new Float32Array(this.N * 3);
    this.alpha = new Float32Array(this.N);
    this.size = new Float32Array(this.N);
    this.life = new Float32Array(this.N);
    this.max = new Float32Array(this.N);

    geo.setAttribute('position', new THREE.BufferAttribute(this.pos, 3));
    geo.setAttribute('aColor', new THREE.BufferAttribute(this.col, 3));
    geo.setAttribute('aLife', new THREE.BufferAttribute(this.alpha, 1));
    geo.setAttribute('aSize', new THREE.BufferAttribute(this.size, 1));

    const mat = new THREE.ShaderMaterial({
      transparent: true,
      depthWrite: false,
      blending: THREE.AdditiveBlending,
      vertexShader: /* glsl */ `
        attribute vec3 aColor;
        attribute float aLife;
        attribute float aSize;
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vColor = aColor;
          vAlpha = aLife;
          vec4 mv = modelViewMatrix * vec4(position, 1.0);
          gl_PointSize = aSize * (340.0 / max(0.1, -mv.z));
          gl_Position = projectionMatrix * mv;
        }
      `,
      fragmentShader: /* glsl */ `
        varying vec3 vColor;
        varying float vAlpha;
        void main() {
          vec2 p = gl_PointCoord - 0.5;
          float d = length(p);
          float a = smoothstep(0.5, 0.05, d);
          gl_FragColor = vec4(vColor, a * vAlpha);
        }
      `,
    });
    this.points = new THREE.Points(geo, mat);
    this.points.frustumCulled = false;
    scene.add(this.points);
    this.geo = geo;

    // tracers
    this.tracers = [];
    const tGeo = new THREE.CylinderGeometry(0.014, 0.014, 1, 5, 1, true);
    for (let i = 0; i < 32; i++) {
      const m = new THREE.Mesh(tGeo, new THREE.MeshBasicMaterial({
        color: 0xffd9a0, transparent: true, opacity: 0, blending: THREE.AdditiveBlending, depthWrite: false,
      }));
      m.visible = false;
      m.frustumCulled = false;
      scene.add(m);
      this.tracers.push({ mesh: m, life: 0, max: 0.1 });
    }
    this.tracerCursor = 0;

    // decals
    this.decals = [];
    const dGeo = new THREE.CircleGeometry(0.5, 14);
    const dTex = scorchTexture();
    for (let i = 0; i < 36; i++) {
      const mat2 = new THREE.MeshBasicMaterial({
        map: dTex, transparent: true, opacity: 0, depthWrite: false,
        polygonOffset: true, polygonOffsetFactor: -4,
      });
      const m = new THREE.Mesh(dGeo, mat2);
      m.visible = false;
      scene.add(m);
      this.decals.push({ mesh: m, life: 0, max: 26 });
    }
    this.decalCursor = 0;

    this.flashTex = radialTexture(128, 'rgba(255,255,240,1)', 'rgba(255,170,70,0.85)', 6);
    this.glowTex = radialTexture(64, 'rgba(255,230,190,1)', 'rgba(255,130,50,0.35)', 0);
  }

  burst(position, normal = new THREE.Vector3(0, 1, 0), color = 0xffb060, count = 16, speed = 6, size = 0.16) {
    const n = new THREE.Vector3().copy(normal).normalize();
    const c = new THREE.Color(color);
    for (let k = 0; k < count; k++) {
      const i = this.cursor;
      this.cursor = (this.cursor + 1) % this.N;
      const i3 = i * 3;
      this.pos[i3] = position.x + n.x * 0.02;
      this.pos[i3 + 1] = position.y + n.y * 0.02;
      this.pos[i3 + 2] = position.z + n.z * 0.02;
      // random direction in hemisphere
      const theta = Math.random() * Math.PI * 2;
      const phi = Math.random() * 0.9;
      const rx = Math.cos(theta) * Math.sin(phi);
      const ry = Math.cos(phi);
      const rz = Math.sin(theta) * Math.sin(phi);
      const t1 = new THREE.Vector3(-n.z, 0.001, n.x).normalize();
      const t2 = new THREE.Vector3().crossVectors(n, t1).normalize();
      const dir = new THREE.Vector3()
        .addScaledVector(n, ry)
        .addScaledVector(t1, rx)
        .addScaledVector(t2, rz)
        .normalize();
      const s = speed * (0.35 + Math.random() * 0.9);
      this.vel[i3] = dir.x * s;
      this.vel[i3 + 1] = dir.y * s + 1.2;
      this.vel[i3 + 2] = dir.z * s;
      const tint = 0.75 + Math.random() * 0.5;
      this.col[i3] = c.r * tint;
      this.col[i3 + 1] = c.g * tint;
      this.col[i3 + 2] = c.b * tint;
      this.max[i] = 0.25 + Math.random() * 0.55;
      this.life[i] = this.max[i];
      this.alpha[i] = 1;
      this.size[i] = size * (0.5 + Math.random());
    }
    this.geo.attributes.aColor.needsUpdate = true;
    this.geo.attributes.aSize.needsUpdate = true;
  }

  muzzle(position, color = 0xffb060) {
    this.burst(position, new THREE.Vector3(0, 0.2, -1).normalize(), color, 6, 3.2, 0.09);
  }

  tracer(from, to, color = 0xffd9a0, width = 1) {
    const t = this.tracers[this.tracerCursor];
    this.tracerCursor = (this.tracerCursor + 1) % this.tracers.length;
    const dir = new THREE.Vector3().subVectors(to, from);
    const len = dir.length();
    if (len < 0.05) return;
    dir.normalize();
    t.mesh.position.copy(from).addScaledVector(dir, len / 2);
    t.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
    t.mesh.scale.set(width, len, width);
    t.mesh.material.color.setHex(color);
    t.mesh.material.opacity = 0.95;
    t.mesh.visible = true;
    t.max = 0.07 + Math.random() * 0.04;
    t.life = t.max;
    t.mesh.renderOrder = 3;
  }

  decal(position, normal, scale = 1) {
    const d = this.decals[this.decalCursor];
    this.decalCursor = (this.decalCursor + 1) % this.decals.length;
    const n = new THREE.Vector3().copy(normal).normalize();
    d.mesh.position.copy(position).addScaledVector(n, 0.015);
    d.mesh.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), n);
    d.mesh.rotateZ(Math.random() * Math.PI * 2);
    d.mesh.scale.setScalar(scale * (0.55 + Math.random() * 0.5));
    d.mesh.material.opacity = 0.9;
    d.mesh.visible = true;
    d.life = d.max;
  }

  impact(position, normal, enemy = false, head = false) {
    if (enemy) {
      this.burst(position, normal, head ? 0xffe2a8 : 0xff8a3c, head ? 26 : 14, head ? 8 : 6, 0.13);
      this.burst(position, normal, 0x8fe8ff, 6, 4, 0.08);
    } else {
      this.burst(position, normal, 0xffb060, 14, 7, 0.12);
      this.burst(position, normal, 0x6a7078, 5, 2.5, 0.16);
      this.decal(position, normal, 0.75);
    }
  }

  update(dt) {
    const g = this.geo;
    for (let i = 0; i < this.N; i++) {
      if (this.life[i] <= 0) { this.alpha[i] = 0; continue; }
      this.life[i] -= dt;
      const i3 = i * 3;
      if (this.life[i] <= 0) { this.alpha[i] = 0; continue; }
      this.vel[i3 + 1] -= 11 * dt;
      const drag = Math.exp(-2.2 * dt);
      this.vel[i3] *= drag; this.vel[i3 + 1] *= drag; this.vel[i3 + 2] *= drag;
      this.pos[i3] += this.vel[i3] * dt;
      this.pos[i3 + 1] += this.vel[i3 + 1] * dt;
      this.pos[i3 + 2] += this.vel[i3 + 2] * dt;
      this.alpha[i] = Math.max(0, this.life[i] / this.max[i]);
    }
    g.attributes.position.needsUpdate = true;
    g.attributes.aLife.needsUpdate = true;

    for (const t of this.tracers) {
      if (t.life > 0) {
        t.life -= dt;
        t.mesh.material.opacity = Math.max(0, (t.life / t.max) * 0.95);
        if (t.life <= 0) t.mesh.visible = false;
      }
    }
    for (const d of this.decals) {
      if (d.life > 0) {
        d.life -= dt;
        if (d.life < 4) d.mesh.material.opacity = Math.max(0, (d.life / 4) * 0.9);
        if (d.life <= 0) d.mesh.visible = false;
      }
    }
  }
}

/* Fully procedural audio — no external assets. */
export class AudioEngine {
  constructor() {
    this.ctx = null;
    this.master = null;
    this.ambientOn = false;
    this.noise = null;
  }

  unlock() {
    if (this.ctx) {
      if (this.ctx.state === 'suspended') this.ctx.resume();
      return;
    }
    const Ctx = window.AudioContext || window.webkitAudioContext;
    if (!Ctx) return;
    const ctx = new Ctx();
    this.ctx = ctx;

    const comp = ctx.createDynamicsCompressor();
    comp.threshold.value = -14;
    comp.knee.value = 20;
    comp.ratio.value = 5;
    comp.attack.value = 0.003;
    comp.release.value = 0.2;

    const master = ctx.createGain();
    master.gain.value = 0.55;
    master.connect(comp);
    comp.connect(ctx.destination);
    this.master = master;

    // reusable noise buffer
    const len = ctx.sampleRate * 1.5;
    const buf = ctx.createBuffer(1, len, ctx.sampleRate);
    const data = buf.getChannelData(0);
    for (let i = 0; i < len; i++) data[i] = Math.random() * 2 - 1;
    this.noise = buf;

    if (ctx.state === 'suspended') ctx.resume();
  }

  now() { return this.ctx ? this.ctx.currentTime : 0; }

  noiseSource() {
    const s = this.ctx.createBufferSource();
    s.buffer = this.noise;
    s.loop = true;
    return s;
  }

  env(gain, t, attack, hold, decay, peak = 1) {
    gain.gain.cancelScheduledValues(t);
    gain.gain.setValueAtTime(0.0001, t);
    gain.gain.linearRampToValueAtTime(peak, t + attack);
    gain.gain.setValueAtTime(peak, t + attack + hold);
    gain.gain.exponentialRampToValueAtTime(0.0001, t + attack + hold + decay);
  }

  noiseBurst({ dur = 0.15, filter = 'lowpass', freq = 1200, q = 0.8, gain = 0.5, delay = 0, sweep = null }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const src = this.noiseSource();
    const f = ctx.createBiquadFilter();
    f.type = filter;
    f.frequency.setValueAtTime(freq, t);
    if (sweep) f.frequency.exponentialRampToValueAtTime(Math.max(40, sweep), t + dur);
    f.Q.value = q;
    const g = ctx.createGain();
    this.env(g, t, 0.002, dur * 0.25, dur * 0.75, gain);
    src.connect(f); f.connect(g); g.connect(this.master);
    src.start(t);
    src.stop(t + dur + 0.05);
  }

  tone({ freq = 440, endFreq = null, dur = 0.15, gain = 0.2, type = 'sine', delay = 0, attack = 0.004 }) {
    if (!this.ctx) return;
    const ctx = this.ctx;
    const t = ctx.currentTime + delay;
    const o = ctx.createOscillator();
    o.type = type;
    o.frequency.setValueAtTime(freq, t);
    if (endFreq) o.frequency.exponentialRampToValueAtTime(Math.max(20, endFreq), t + dur);
    const g = ctx.createGain();
    this.env(g, t, attack, dur * 0.2, dur * 0.8, gain);
    o.connect(g); g.connect(this.master);
    o.start(t); o.stop(t + dur + 0.05);
  }

  shot() {
    if (!this.ctx) return;
    const t = this.ctx.currentTime;
    // body
    this.noiseBurst({ dur: 0.22, filter: 'lowpass', freq: 3600, sweep: 320, gain: 0.85 });
    this.noiseBurst({ dur: 0.05, filter: 'highpass', freq: 3800, gain: 0.5 });
    // thump
    this.tone({ freq: 170, endFreq: 42, dur: 0.2, gain: 0.75, type: 'sine' });
    this.tone({ freq: 92, endFreq: 40, dur: 0.26, gain: 0.4, type: 'triangle' });
    // mechanical click
    this.tone({ freq: 2600, endFreq: 1200, dur: 0.03, gain: 0.06, type: 'square', delay: 0.015 });
  }

  enemyShot() {
    if (!this.ctx) return;
    this.noiseBurst({ dur: 0.16, filter: 'lowpass', freq: 2200, sweep: 240, gain: 0.28 });
    this.tone({ freq: 130, endFreq: 50, dur: 0.16, gain: 0.22, type: 'sawtooth' });
  }

  empty() {
    this.tone({ freq: 900, endFreq: 500, dur: 0.04, gain: 0.08, type: 'square' });
  }

  hit(kill = false, head = false) {
    if (!this.ctx) return;
    if (kill) {
      this.tone({ freq: 1600, endFreq: 900, dur: 0.08, gain: 0.16, type: 'triangle' });
      this.tone({ freq: 2400, endFreq: 1800, dur: 0.06, gain: 0.08, type: 'square', delay: 0.04 });
    } else if (head) {
      this.tone({ freq: 2100, endFreq: 1500, dur: 0.05, gain: 0.12, type: 'square' });
    } else {
      this.tone({ freq: 1100, endFreq: 800, dur: 0.045, gain: 0.09, type: 'square' });
    }
  }

  reload() {
    if (!this.ctx) return;
    this.tone({ freq: 420, endFreq: 260, dur: 0.05, gain: 0.1, type: 'square', delay: 0.12 });
    this.tone({ freq: 300, endFreq: 190, dur: 0.06, gain: 0.12, type: 'square', delay: 0.9 });
    this.tone({ freq: 700, endFreq: 380, dur: 0.05, gain: 0.1, type: 'square', delay: 1.55 });
    this.noiseBurst({ dur: 0.05, filter: 'bandpass', freq: 1800, q: 2, gain: 0.1, delay: 1.62 });
  }

  step(sprint = false) {
    if (!this.ctx) return;
    this.noiseBurst({ dur: 0.075, filter: 'lowpass', freq: sprint ? 720 : 520, q: 1.2, gain: sprint ? 0.14 : 0.09 });
    this.tone({ freq: 90, endFreq: 55, dur: 0.07, gain: 0.05, type: 'sine' });
  }

  hurt() {
    if (!this.ctx) return;
    this.noiseBurst({ dur: 0.18, filter: 'lowpass', freq: 700, gain: 0.3 });
    this.tone({ freq: 120, endFreq: 60, dur: 0.25, gain: 0.3, type: 'sawtooth' });
  }

  wave() {
    if (!this.ctx) return;
    this.tone({ freq: 150, endFreq: 96, dur: 0.9, gain: 0.28, type: 'sawtooth', attack: 0.08 });
    this.tone({ freq: 300, endFreq: 190, dur: 0.7, gain: 0.12, type: 'triangle', delay: 0.12, attack: 0.1 });
    this.noiseBurst({ dur: 0.8, filter: 'bandpass', freq: 400, q: 0.7, gain: 0.08, delay: 0.1 });
  }

  gameOver() {
    if (!this.ctx) return;
    this.tone({ freq: 220, endFreq: 80, dur: 1.4, gain: 0.3, type: 'sawtooth', attack: 0.02 });
    this.tone({ freq: 110, endFreq: 42, dur: 1.8, gain: 0.25, type: 'sine' });
  }

  ambient() {
    if (!this.ctx || this.ambientOn) return;
    this.ambientOn = true;
    const ctx = this.ctx;
    // low industrial drone
    const o1 = ctx.createOscillator();
    o1.type = 'sine'; o1.frequency.value = 46;
    const o2 = ctx.createOscillator();
    o2.type = 'sine'; o2.frequency.value = 57.3;
    const og = ctx.createGain(); og.gain.value = 0.05;
    const lp = ctx.createBiquadFilter(); lp.type = 'lowpass'; lp.frequency.value = 190;
    o1.connect(og); o2.connect(og); og.connect(lp); lp.connect(this.master);
    o1.start(); o2.start();

    // wind
    const wind = this.noiseSource();
    const bp = ctx.createBiquadFilter(); bp.type = 'bandpass'; bp.frequency.value = 320; bp.Q.value = 0.55;
    const wg = ctx.createGain(); wg.gain.value = 0.03;
    const lfo = ctx.createOscillator(); lfo.frequency.value = 0.08;
    const lfoG = ctx.createGain(); lfoG.gain.value = 0.025;
    lfo.connect(lfoG); lfoG.connect(wg.gain);
    wind.connect(bp); bp.connect(wg); wg.connect(this.master);
    wind.start(); lfo.start();
  }
}

export class HUD {
  constructor() {
    const $ = (id) => document.getElementById(id);
    this.root = $('hud');
    this.waveEl = $('wave');
    this.hostilesEl = $('hostiles');
    this.scoreEl = $('score');
    this.healthBar = $('healthbar');
    this.healthNum = $('healthnum');
    this.status = $('status');
    this.ammoEl = $('ammo');
    this.ammoMag = $('ammo-mag');
    this.ammoReserve = $('ammo-reserve');
    this.reloadHint = $('reload-hint');
    this.crosshair = $('crosshair');
    this.hitmarker = $('hitmarker');
    this.killfeed = $('killfeed');
    this.banner = $('banner');
    this.bannerTitle = $('banner-title');
    this.bannerSub = $('banner-sub');
    this.damageEl = $('damage');
    this.flashEl = $('flash');
    this.fpsEl = $('fps');

    this._bannerTimer = null;
    this._damageTimer = null;
    this._fpsAccum = 0;
    this._fpsFrames = 0;
  }

  show() { this.root.classList.remove('hidden'); }
  hide() { this.root.classList.add('hidden'); }

  setHealth(hp, max = 100) {
    const pct = Math.max(0, Math.min(1, hp / max));
    this.healthBar.style.width = `${pct * 100}%`;
    this.healthNum.textContent = Math.max(0, Math.round(hp));
    this.healthBar.classList.toggle('low', pct <= 0.34);
    this.status.textContent = pct > 0.66 ? 'NOMINAL' : pct > 0.34 ? 'DAMAGED' : 'CRITICAL';
  }

  setAmmo(mag, reserve, reloading = false) {
    this.ammoMag.textContent = String(mag).padStart(2, '0');
    this.ammoReserve.textContent = String(reserve).padStart(3, '0');
    this.ammoEl.classList.toggle('empty', mag === 0);
    this.ammoEl.classList.toggle('low', mag > 0 && mag <= 8);
    this.reloadHint.textContent = reloading ? 'RELOADING...' : 'RELOAD [R]';
  }

  setStats({ wave, hostiles, score }) {
    if (wave !== undefined) this.waveEl.textContent = String(wave).padStart(2, '0');
    if (hostiles !== undefined) this.hostilesEl.textContent = String(hostiles).padStart(2, '0');
    if (score !== undefined) this.scoreEl.textContent = String(score).padStart(6, '0');
  }

  hit(kill = false, head = false) {
    const el = this.hitmarker;
    el.classList.remove('show', 'kill', 'head');
    void el.offsetWidth;
    el.classList.add('show');
    if (kill) el.classList.add('kill');
    else if (head) el.classList.add('head');
  }

  feed(text, head = false, kill = true) {
    const el = document.createElement('div');
    el.className = 'kill-item';
    el.innerHTML = `<span>${text}</span>${head ? '<span class="hs">HEADSHOT</span>' : ''}${kill ? '<b>+150</b>' : ''}`;
    this.killfeed.appendChild(el);
    while (this.killfeed.children.length > 5) this.killfeed.firstChild.remove();
    setTimeout(() => {
      el.style.transition = 'opacity .4s, transform .4s';
      el.style.opacity = '0';
      el.style.transform = 'translateX(20px)';
      setTimeout(() => el.remove(), 420);
    }, 3800);
  }

  damage() {
    this.damageEl.style.opacity = '1';
    clearTimeout(this._damageTimer);
    this._damageTimer = setTimeout(() => { this.damageEl.style.opacity = '0'; }, 160);
  }

  flash(a = 0.4) {
    this.flashEl.style.transition = 'none';
    this.flashEl.style.opacity = String(a);
    requestAnimationFrame(() => {
      this.flashEl.style.transition = 'opacity .3s';
      this.flashEl.style.opacity = '0';
    });
  }

  banner(title, sub, duration = 2200) {
    this.bannerTitle.textContent = title;
    this.bannerSub.textContent = sub;
    this.banner.classList.add('show');
    clearTimeout(this._bannerTimer);
    if (duration > 0) {
      this._bannerTimer = setTimeout(() => this.banner.classList.remove('show'), duration);
    }
  }

  hideBanner() {
    this.banner.classList.remove('show');
  }

  ads(on) { this.crosshair.classList.toggle('ads', on); }

  lowHealthPulse(on) {
    this.healthNum.style.animation = on ? 'none' : '';
  }

  fps(dt) {
    this._fpsAccum += dt;
    this._fpsFrames++;
    if (this._fpsAccum >= 0.5) {
      this.fpsEl.textContent = `${Math.round(this._fpsFrames / this._fpsAccum)} FPS`;
      this._fpsAccum = 0;
      this._fpsFrames = 0;
    }
  }
}

