import * as THREE from 'three';

/* Push a circle (XZ) out of axis-aligned boxes. */
export function resolveCircle(pos, radius, colliders, height = 1.8) {
  for (const b of colliders) {
    if (b.max.y < pos.y + 0.25 || b.min.y > pos.y + height) continue;
    const cx = Math.max(b.min.x, Math.min(pos.x, b.max.x));
    const cz = Math.max(b.min.z, Math.min(pos.z, b.max.z));
    let dx = pos.x - cx;
    let dz = pos.z - cz;
    const d2 = dx * dx + dz * dz;
    if (d2 > radius * radius) continue;
    if (d2 > 1e-8) {
      const d = Math.sqrt(d2);
      pos.x += (dx / d) * (radius - d);
      pos.z += (dz / d) * (radius - d);
    } else {
      const left = pos.x - b.min.x;
      const right = b.max.x - pos.x;
      const back = pos.z - b.min.z;
      const front = b.max.z - pos.z;
      const m = Math.min(left, right, back, front);
      if (m === left) pos.x = b.min.x - radius;
      else if (m === right) pos.x = b.max.x + radius;
      else if (m === back) pos.z = b.min.z - radius;
      else pos.z = b.max.z + radius;
    }
  }
}

const _ray = new THREE.Raycaster();
const _dir = new THREE.Vector3();

export function lineBlocked(from, to, meshes) {
  _dir.subVectors(to, from);
  const dist = _dir.length();
  if (dist < 0.001) return false;
  _dir.multiplyScalar(1 / dist);
  _ray.set(from, _dir);
  _ray.far = dist - 0.05;
  _ray.near = 0.01;
  const hits = _ray.intersectObjects(meshes, false);
  return hits.length > 0;
}

export function randRange(a, b) { return a + Math.random() * (b - a); }

import * as THREE from 'three';
import { resolveCircle } from './util.js';

const BASE_FOV = 76;
const ADS_FOV = 52;

export class Player {
  constructor(camera, world, audio, hud) {
    this.camera = camera;
    this.colliders = world.colliders;
    this.audio = audio;
    this.hud = hud;

    this.pos = new THREE.Vector3(0, 0, 21);
    this.yaw = 0;
    this.pitch = -0.03;
    this.vel = new THREE.Vector3();
    this.vy = 0;
    this.onGround = true;

    this.maxHealth = 100;
    this.health = 100;
    this.alive = true;
    this.lastDamage = -999;
    this.ads = false;
    this.sprinting = false;
    this.crouching = false;
    this.eye = 1.68;
    this.eyeCurrent = 1.68;

    this.bobTime = 0;
    this.bobAmount = 0;
    this.roll = 0;

    this.recoilPitch = 0;
    this.recoilYaw = 0;
    this.shake = 0;
    this.shakeSeed = Math.random() * 100;

    this.stepAccum = 0;
    this.sensitivity = 0.0021;
    this.speed = 0;
    this._moved = new THREE.Vector3();
  }

  reset() {
    this.pos.set(0, 0, 21);
    this.yaw = 0;
    this.pitch = -0.03;
    this.vel.set(0, 0, 0);
    this.vy = 0;
    this.health = this.maxHealth;
    this.alive = true;
    this.lastDamage = -999;
    this.ads = false;
    this.eyeCurrent = this.eye;
    this.recoilPitch = this.recoilYaw = 0;
    this.shake = 0;
    this.camera.fov = BASE_FOV;
    this.camera.updateProjectionMatrix();
    this.hud.setHealth(this.health);
  }

  look(dx, dy) {
    if (!this.alive) return;
    const sens = this.sensitivity * (this.ads ? 0.62 : 1);
    this.yaw -= dx * sens;
    this.pitch -= dy * sens;
    const lim = Math.PI / 2 - 0.04;
    this.pitch = Math.max(-lim, Math.min(lim, this.pitch));
  }

  addRecoil(pitch, yaw) {
    this.recoilPitch += pitch;
    this.recoilYaw += yaw;
  }

  setAds(on) {
    this.ads = on;
  }

  damage(amount, from = null) {
    if (!this.alive) return;
    this.health = Math.max(0, this.health - amount);
    this.lastDamage = performance.now() / 1000;
    this.shake = Math.min(0.05, this.shake + 0.018);
    this.hud.damage();
    this.hud.setHealth(this.health, this.maxHealth);
    this.audio.hurt();
    if (this.health <= 0) {
      this.alive = false;
    }
  }

  update(dt, input) {
    const now = performance.now() / 1000;

    // regen after 6s
    if (this.alive && now - this.lastDamage > 6 && this.health < this.maxHealth) {
      this.health = Math.min(this.maxHealth, this.health + 9 * dt);
      this.hud.setHealth(this.health, this.maxHealth);
    }

    this.crouching = !!input.crouch;
    this.sprinting = !!input.sprint && !this.ads && !this.crouching && this.alive;

    const fwd = (input.forward ? 1 : 0) - (input.back ? 1 : 0);
    const strafe = (input.right ? 1 : 0) - (input.left ? 1 : 0);
    const dir = new THREE.Vector3();
    if (fwd || strafe) {
      const sin = Math.sin(this.yaw), cos = Math.cos(this.yaw);
      dir.x = -sin * fwd + cos * strafe;
      dir.z = -cos * fwd - sin * strafe;
      dir.normalize();
    }

    let speed = 5.6;
    if (this.ads) speed = 3.4;
    if (this.crouching) speed = 2.5;
    if (this.sprinting) speed = 8.6;

    const accel = this.onGround ? 11 : 2.4;
    const k = 1 - Math.exp(-accel * dt);
    this.vel.x += (dir.x * speed - this.vel.x) * k;
    this.vel.z += (dir.z * speed - this.vel.z) * k;

    // jump / gravity
    if (input.jump && this.onGround && this.alive) {
      this.vy = 6.4;
      this.onGround = false;
    }
    this.vy -= 21 * dt;
    this.pos.y += this.vy * dt;
    if (this.pos.y <= 0) {
      this.pos.y = 0;
      this.vy = 0;
      this.onGround = true;
    }

    this.pos.x += this.vel.x * dt;
    this.pos.z += this.vel.z * dt;
    resolveCircle(this.pos, 0.38, this.colliders, 1.8);

    // clamp to arena
    this.pos.x = Math.max(-33, Math.min(33, this.pos.x));
    this.pos.z = Math.max(-33, Math.min(33, this.pos.z));

    // movement feedback
    const hSpeed = Math.hypot(this.vel.x, this.vel.z);
    this.speed = hSpeed;
    this.bobTime += dt * hSpeed * 1.35;
    const targetBob = this.onGround ? Math.min(1, hSpeed / 6) : 0;
    this.bobAmount += (targetBob - this.bobAmount) * Math.min(1, dt * 8);

    // footsteps
    if (this.onGround && hSpeed > 1.2) {
      this.stepAccum += hSpeed * dt;
      const stride = this.sprinting ? 2.35 : 2.0;
      if (this.stepAccum > stride) {
        this.stepAccum = 0;
        this.audio.step(this.sprinting);
      }
    }

    // eye height / crouch
    const targetEye = this.crouching ? 1.08 : 1.68;
    this.eyeCurrent += (targetEye - this.eyeCurrent) * Math.min(1, dt * 9);

    // recoil recovery
    const rec = Math.exp(-dt * 7.5);
    this.recoilPitch *= rec;
    this.recoilYaw *= rec;
    this.shake *= Math.exp(-dt * 6);

    // fov
    const targetFov = this.ads ? ADS_FOV : BASE_FOV;
    if (Math.abs(this.camera.fov - targetFov) > 0.05) {
      this.camera.fov += (targetFov - this.camera.fov) * Math.min(1, dt * 12);
      this.camera.updateProjectionMatrix();
    }

    // camera transform
    const bobY = Math.sin(this.bobTime * 2) * 0.026 * this.bobAmount;
    const bobX = Math.cos(this.bobTime) * 0.03 * this.bobAmount;
    const shakeT = now * 42;
    const shakeX = Math.sin(shakeT * 1.7 + this.shakeSeed) * this.shake;
    const shakeY = Math.cos(shakeT * 1.3 + this.shakeSeed) * this.shake;

    this.camera.position.set(this.pos.x + bobX * 0.4, this.pos.y + this.eyeCurrent + bobY, this.pos.z);
    this.camera.rotation.order = 'YXZ';

    const targetRoll = (this.ads ? 0 : -strafe * 0.012) + Math.cos(this.bobTime) * 0.004 * this.bobAmount;
    this.roll += (targetRoll - this.roll) * Math.min(1, dt * 6);

    this.camera.rotation.set(
      this.pitch + this.recoilPitch + shakeY,
      this.yaw + this.recoilYaw + shakeX,
      this.roll
    );
  }
}

import * as THREE from 'three';

const MAG_SIZE = 30;
const RESERVE_START = 150;
const FIRE_RATE = 0.095;
const RELOAD_TIME = 1.75;

function reticleTexture() {
  const s = 128;
  const c = document.createElement('canvas');
  c.width = c.height = s;
  const ctx = c.getContext('2d');
  ctx.clearRect(0, 0, s, s);
  ctx.strokeStyle = 'rgba(120,240,255,0.95)';
  ctx.lineWidth = 3;
  ctx.beginPath();
  ctx.arc(s / 2, s / 2, 26, 0, Math.PI * 2);
  ctx.stroke();
  ctx.fillStyle = 'rgba(160,250,255,1)';
  ctx.beginPath();
  ctx.arc(s / 2, s / 2, 4, 0, Math.PI * 2);
  ctx.fill();
  for (const [x1, y1, x2, y2] of [[64, 8, 64, 24], [64, 104, 64, 120], [8, 64, 24, 64], [104, 64, 120, 64]]) {
    ctx.beginPath(); ctx.moveTo(x1, y1); ctx.lineTo(x2, y2); ctx.stroke();
  }
  const t = new THREE.CanvasTexture(c);
  t.colorSpace = THREE.SRGBColorSpace;
  return t;
}

export class Weapon {
  constructor(camera, scene, world, enemies, fx, audio, hud, player, callbacks = {}) {
    this.camera = camera;
    this.scene = scene;
    this.world = world;
    this.enemies = enemies;
    this.fx = fx;
    this.audio = audio;
    this.hud = hud;
    this.player = player;
    this.onKill = callbacks.onKill || (() => {});
    this.onShot = callbacks.onShot || (() => {});

    this.mag = MAG_SIZE;
    this.reserve = RESERVE_START;
    this.reloading = false;
    this.reloadT = 0;
    this.cooldown = 0;
    this.bloom = 0;
    this.kickZ = 0;
    this.kickRot = 0;
    this.kickRoll = 0;
    this.flashTime = 0;
    this.triggerHeld = false;

    this.raycaster = new THREE.Raycaster();
    this.raycaster.far = 200;

    this.root = new THREE.Group();
    this.root.position.set(0.2, -0.2, -0.42);
    camera.add(this.root);
    this.build();

    this.hud.setAmmo(this.mag, this.reserve);
  }

  build() {
    const gunmetal = new THREE.MeshStandardMaterial({ color: 0x33383e, metalness: 0.92, roughness: 0.32 });
    const dark = new THREE.MeshStandardMaterial({ color: 0x1a1d21, metalness: 0.75, roughness: 0.5 });
    const polymer = new THREE.MeshStandardMaterial({ color: 0x141619, metalness: 0.2, roughness: 0.72 });
    const accent = new THREE.MeshStandardMaterial({
      color: 0x38160a, emissive: 0xff6a18, emissiveIntensity: 2.6, metalness: 0.4, roughness: 0.4,
    });
    const glass = new THREE.MeshBasicMaterial({
      color: 0x6fe8ff, transparent: true, opacity: 0.16, blending: THREE.AdditiveBlending, depthWrite: false,
    });

    const add = (geo, mat, x, y, z, rx = 0, ry = 0, rz = 0, parent = this.root) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.rotation.set(rx, ry, rz);
      m.castShadow = false;
      m.receiveShadow = false;
      parent.add(m);
      return m;
    };

    // receiver + rail
    add(new THREE.BoxGeometry(0.082, 0.105, 0.4), gunmetal, 0, 0, 0);
    add(new THREE.BoxGeometry(0.058, 0.026, 0.42), dark, 0, 0.066, -0.01);
    for (let i = 0; i < 9; i++) {
      add(new THREE.BoxGeometry(0.06, 0.012, 0.014), gunmetal, 0, 0.083, -0.2 + i * 0.045);
    }

    // handguard
    add(new THREE.BoxGeometry(0.07, 0.072, 0.27), polymer, 0, 0.005, -0.34);
    for (let i = 0; i < 5; i++) {
      add(new THREE.BoxGeometry(0.075, 0.012, 0.016), gunmetal, 0, 0.008, -0.44 + i * 0.045);
      add(new THREE.BoxGeometry(0.012, 0.06, 0.016), dark, 0.038, 0.006, -0.44 + i * 0.045);
      add(new THREE.BoxGeometry(0.012, 0.06, 0.016), dark, -0.038, 0.006, -0.44 + i * 0.045);
    }

    // barrel + muzzle
    add(new THREE.CylinderGeometry(0.017, 0.017, 0.36, 12), gunmetal, 0, 0.005, -0.58, Math.PI / 2, 0, 0);
    add(new THREE.CylinderGeometry(0.03, 0.03, 0.09, 12), dark, 0, 0.005, -0.77, Math.PI / 2, 0, 0);
    for (let i = 0; i < 3; i++) {
      add(new THREE.BoxGeometry(0.072, 0.012, 0.012), gunmetal, 0, 0.005, -0.74 - i * 0.03);
    }

    // stock
    add(new THREE.BoxGeometry(0.05, 0.09, 0.24), polymer, 0, -0.012, 0.29);
    add(new THREE.BoxGeometry(0.058, 0.13, 0.05), dark, 0, -0.02, 0.41);
    add(new THREE.BoxGeometry(0.062, 0.035, 0.14), polymer, 0, 0.055, 0.24);

    // grip + magazine + trigger guard
    add(new THREE.BoxGeometry(0.048, 0.15, 0.07), polymer, 0, -0.115, 0.1, 0.32, 0, 0);
    add(new THREE.BoxGeometry(0.048, 0.19, 0.1), dark, 0, -0.135, -0.06, -0.18, 0, 0);
    add(new THREE.BoxGeometry(0.052, 0.02, 0.1), gunmetal, 0, -0.086, -0.03);
    add(new THREE.BoxGeometry(0.012, 0.055, 0.075), gunmetal, 0, -0.072, 0.032, 0, 0, 0);
    // accent strips
    add(new THREE.BoxGeometry(0.004, 0.012, 0.16), accent, 0.043, 0.02, -0.02);
    add(new THREE.BoxGeometry(0.004, 0.012, 0.1), accent, -0.043, 0.02, -0.06);

    // holo sight
    const sightY = 0.092;
    add(new THREE.BoxGeometry(0.06, 0.018, 0.1), dark, 0, sightY, -0.02);
    add(new THREE.BoxGeometry(0.01, 0.06, 0.045), gunmetal, -0.03, sightY + 0.035, -0.03);
    add(new THREE.BoxGeometry(0.01, 0.06, 0.045), gunmetal, 0.03, sightY + 0.035, -0.03);
    add(new THREE.BoxGeometry(0.07, 0.01, 0.045), gunmetal, 0, sightY + 0.065, -0.03);
    const glassMesh = add(new THREE.PlaneGeometry(0.052, 0.048), glass, 0, sightY + 0.037, -0.008);
    glassMesh.rotation.y = Math.PI;

    // reticle (must sit on the camera axis when aiming)
    const retMat = new THREE.MeshBasicMaterial({
      map: reticleTexture(), transparent: true, blending: THREE.AdditiveBlending,
      depthWrite: false, opacity: 0.95,
    });
    const ret = add(new THREE.PlaneGeometry(0.042, 0.042), retMat, 0, sightY + 0.037, -0.004);
    ret.rotation.y = Math.PI;

    // laser module
    add(new THREE.BoxGeometry(0.032, 0.032, 0.075), dark, 0.052, 0.01, -0.36);
    add(new THREE.SphereGeometry(0.009, 8, 6), new THREE.MeshBasicMaterial({ color: 0xff2a10 }), 0.052, 0.01, -0.4);

    // gloved hands / sleeves
    const glove = new THREE.MeshStandardMaterial({ color: 0x23262a, roughness: 0.85, metalness: 0.05 });
    const sleeve = new THREE.MeshStandardMaterial({ color: 0x3a4034, roughness: 0.95, metalness: 0.0 });
    // right hand on grip
    const rh = add(new THREE.BoxGeometry(0.07, 0.09, 0.09), glove, 0, -0.1, 0.1);
    rh.rotation.x = 0.35;
    add(new THREE.CapsuleGeometry(0.045, 0.22, 4, 8), sleeve, 0.03, -0.22, 0.22, -0.72, 0.15, 0.18);
    // left hand on handguard
    const lh = add(new THREE.BoxGeometry(0.08, 0.075, 0.1), glove, -0.005, -0.055, -0.33);
    lh.rotation.z = -0.2;
    add(new THREE.CapsuleGeometry(0.042, 0.24, 4, 8), sleeve, -0.08, -0.18, -0.2, -0.45, -0.2, 0.5);

    // muzzle anchor + flash
    this.muzzle = new THREE.Object3D();
    this.muzzle.position.set(0, 0.005, -0.84);
    this.root.add(this.muzzle);

    const flashMat = new THREE.SpriteMaterial({
      map: this.fx.flashTex, color: 0xffe0b0, transparent: true, opacity: 0,
      blending: THREE.AdditiveBlending, depthWrite: false, depthTest: false,
    });
    this.flash = new THREE.Sprite(flashMat);
    this.flash.scale.setScalar(0.4);
    this.flash.position.set(0, 0.005, -0.86);
    this.flash.visible = false;
    this.root.add(this.flash);

    this.flashLight = new THREE.PointLight(0xffb060, 0, 7, 2);
    this.flashLight.position.set(0, 0.02, -0.7);
    this.root.add(this.flashLight);

    // store animated bits
    this.baseRootPos = this.root.position.clone();
    this.reloadGroup = this.root;
  }

  reset() {
    this.mag = MAG_SIZE;
    this.reserve = RESERVE_START;
    this.reloading = false;
    this.reloadT = 0;
    this.cooldown = 0;
    this.bloom = 0;
    this.kickZ = this.kickRot = this.kickRoll = 0;
    this.flashTime = 0;
    this.root.rotation.set(0, 0, 0);
    this.hud.setAmmo(this.mag, this.reserve);
  }

  startReload() {
    if (this.reloading || this.mag === MAG_SIZE || this.reserve <= 0) return;
    this.reloading = true;
    this.reloadT = 0;
    this.audio.reload();
    this.hud.setAmmo(this.mag, this.reserve, true);
  }

  finishReload() {
    const need = MAG_SIZE - this.mag;
    const take = Math.min(need, this.reserve);
    this.mag += take;
    this.reserve -= take;
    this.reloading = false;
    this.hud.setAmmo(this.mag, this.reserve);
  }

  setTrigger(down) {
    this.triggerHeld = down;
    if (down) this.tryFire();
  }

  tryFire() {
    if (this.reloading || !this.player.alive) return;
    if (this.cooldown > 0) return;
    if (this.mag <= 0) {
      this.audio.empty();
      this.cooldown = 0.25;
      this.startReload();
      return;
    }

    this.mag--;
    this.cooldown = FIRE_RATE;
    this.bloom = Math.min(0.02, this.bloom + 0.0022);
    this.audio.shot();
    this.player.addRecoil(0.0085 + Math.random() * 0.004, (Math.random() - 0.5) * 0.006);
    this.kickZ = Math.min(0.09, this.kickZ + 0.055);
    this.kickRot = Math.min(0.16, this.kickRot + 0.1);
    this.kickRoll = (Math.random() - 0.5) * 0.06;
    this.flashTime = 0.05;
    this.flash.visible = true;
    this.flash.material.opacity = 1;
    this.flash.material.rotation = Math.random() * Math.PI;
    this.flash.scale.setScalar(0.32 + Math.random() * 0.16);
    this.flashLight.intensity = 12;

    const muzzlePos = new THREE.Vector3();
    this.muzzle.getWorldPosition(muzzlePos);
    this.fx.muzzle(muzzlePos, 0xffc070);
    this.hud.setAmmo(this.mag, this.reserve);

    // spread cone
    const dir = new THREE.Vector3();
    this.camera.getWorldDirection(dir);
    const right = new THREE.Vector3().setFromMatrixColumn(this.camera.matrixWorld, 0);
    const up = new THREE.Vector3().setFromMatrixColumn(this.camera.matrixWorld, 1);
    const spread = (this.player.ads ? 0.0016 : 0.0075) + this.bloom + Math.min(0.01, this.player.speed * 0.0011);
    const a = Math.random() * Math.PI * 2;
    const r = Math.sqrt(Math.random()) * spread;
    dir.addScaledVector(right, Math.cos(a) * r).addScaledVector(up, Math.sin(a) * r).normalize();

    this.raycaster.set(this.camera.getWorldPosition(new THREE.Vector3()), dir);
    const targets = this.world.raycastMeshes.concat(this.enemies.hitMeshes);
    const hits = this.raycaster.intersectObjects(targets, false);
    let end = this.raycaster.ray.at(120, new THREE.Vector3());

    if (hits.length) {
      const hit = hits[0];
      end = hit.point.clone();
      const data = hit.object.userData;
      if (data.enemy && !data.enemy.dead) {
        const head = data.part === 'head';
        const dmg = head ? 68 : 26;
        const killed = data.enemy.takeDamage(dmg, head);
        const normal = hit.face
          ? hit.face.normal.clone().transformDirection(hit.object.matrixWorld)
          : dir.clone().negate();
        this.fx.impact(hit.point, normal, true, head);
        this.hud.hit(killed, head);
        this.audio.hit(killed, head);
        if (killed) {
          this.hud.feed('MK-17 ▸ SENTINEL', head);
          this.onKill(data.enemy, head);
        }
      } else {
        const normal = hit.face
          ? hit.face.normal.clone().transformDirection(hit.object.matrixWorld)
          : dir.clone().negate();
        this.fx.impact(hit.point, normal, false, false);
      }
    }

    this.fx.tracer(muzzlePos, end, 0xffd9a0, 1);
    this.onShot();

    if (this.mag === 0 && this.reserve > 0) {
      setTimeout(() => this.startReload(), 220);
    }
  }

  update(dt, input) {
    this.cooldown = Math.max(0, this.cooldown - dt);
    this.bloom = Math.max(0, this.bloom - dt * 0.012);

    if (this.reloading) {
      this.reloadT += dt;
      if (this.reloadT >= RELOAD_TIME) this.finishReload();
    }

    const ads = this.player.ads && !this.reloading;
    const sprint = this.player.sprinting && !this.reloading;
    this.hud.ads(ads);

    // model pose
    const bob = this.player.bobTime;
    const bobAmt = this.player.bobAmount;
    const swayX = Math.sin(bob) * 0.006 * bobAmt;
    const swayY = Math.sin(bob * 2) * 0.005 * bobAmt;

    let px = 0.205 + swayX;
    let py = -0.205 + swayY;
    let pz = -0.42;
    let rx = 0, ry = 0, rz = 0;

    if (ads) {
      px = 0 + swayX * 0.25;
      py = -0.092 + swayY * 0.25;
      pz = -0.34;
      rx = 0; ry = 0; rz = 0;
    }
    if (sprint) {
      px = 0.17 + swayX * 1.4;
      py = -0.28 + swayY * 1.4;
      pz = -0.36;
      rx = -0.1; ry = -0.28; rz = 0.42;
    }
    if (this.reloading) {
      const t = Math.min(1, this.reloadT / RELOAD_TIME);
      const dip = Math.sin(Math.PI * Math.min(1, t * 1.05));
      py -= 0.2 * dip;
      px += 0.04 * dip;
      rz += 0.55 * dip;
      rx -= 0.32 * dip;
    }

    const k = 1 - Math.exp(-dt * 13);
    this.root.position.x += (px - this.root.position.x) * k;
    this.root.position.y += (py - this.root.position.y) * k;
    this.root.position.z += (pz - this.root.position.z) * k;

    // recoil springs
    this.kickZ *= Math.exp(-dt * 15);
    this.kickRot *= Math.exp(-dt * 12);
    this.kickRoll *= Math.exp(-dt * 12);

    this.root.position.z += this.kickZ;
    this.root.rotation.x += (rx + this.kickRot - this.root.rotation.x) * k;
    this.root.rotation.y += (ry - this.root.rotation.y) * k;
    this.root.rotation.z += (rz + this.kickRoll - this.root.rotation.z) * k;

    // muzzle flash decay
    if (this.flashTime > 0) {
      this.flashTime -= dt;
      this.flash.material.opacity = Math.max(0, this.flashTime / 0.05);
      this.flashLight.intensity = Math.max(0, this.flashLight.intensity - dt * 400);
      if (this.flashTime <= 0) this.flash.visible = false;
    }

    if (input.fire && !this.reloading) this.tryFire();
  }
}

import * as THREE from 'three';
import { resolveCircle, lineBlocked } from './util.js';

const ONE = new THREE.Vector3(1, 1, 1);

export class Enemy {
  constructor(manager, position, wave) {
    this.manager = manager;
    this.scene = manager.scene;
    this.world = manager.world;
    this.player = manager.player;
    this.fx = manager.fx;
    this.audio = manager.audio;

    this.maxHp = 100 + wave * 12;
    this.hp = this.maxHp;
    this.dead = false;
    this.deathT = 0;
    this.hitFlash = 0;
    this.walkPhase = Math.random() * Math.PI * 2;
    this.speed = 2.1 + Math.min(1.4, wave * 0.14);
    this.state = 'spawn';
    this.spawnT = 0;
    this.nextShot = 1.2 + Math.random() * 2;
    this.burst = 0;
    this.burstT = 0;
    this.los = false;
    this.losT = Math.random() * 0.2;
    this.strafeDir = Math.random() > 0.5 ? 1 : -1;
    this.strafeT = 1.5 + Math.random() * 2;
    this.aimFlash = 0;

    this.group = new THREE.Group();
    this.group.position.copy(position);
    this.group.scale.set(1, 0.01, 1);
    this.scene.add(this.group);

    this.hitMeshes = [];
    this.build(wave);
    this.group.updateMatrixWorld(true);
  }

  build(wave) {
    const armor = new THREE.MeshStandardMaterial({ color: 0x2c3238, metalness: 0.85, roughness: 0.38 });
    const plate = new THREE.MeshStandardMaterial({ color: 0x1a1f24, metalness: 0.7, roughness: 0.5 });
    const trim = new THREE.MeshStandardMaterial({ color: 0x22262b, metalness: 0.6, roughness: 0.45 });
    const glow = new THREE.MeshStandardMaterial({
      color: 0x1a0d06, emissive: 0xff5a16, emissiveIntensity: 2.4, metalness: 0.3, roughness: 0.4,
    });
    const eye = new THREE.MeshStandardMaterial({
      color: 0x0a0a0a, emissive: 0xff7a22, emissiveIntensity: 6, metalness: 0.2, roughness: 0.3,
    });
    const gunMat = new THREE.MeshStandardMaterial({ color: 0x191c20, metalness: 0.85, roughness: 0.35 });
    this.mats = [armor, plate, trim, glow];

    const part = (geo, mat, x, y, z, parent = this.group, tag = null) => {
      const m = new THREE.Mesh(geo, mat);
      m.position.set(x, y, z);
      m.castShadow = true;
      m.receiveShadow = true;
      parent.add(m);
      if (tag) {
        m.userData.enemy = this;
        m.userData.part = tag;
        this.hitMeshes.push(m);
      }
      return m;
    };

    // legs
    this.legs = [];
    for (const s of [-1, 1]) {
      const hip = new THREE.Group();
      hip.position.set(s * 0.15, 1.0, 0);
      this.group.add(hip);
      part(new THREE.BoxGeometry(0.17, 0.45, 0.19), plate, 0, -0.225, 0, hip, 'body');
      const knee = new THREE.Group();
      knee.position.set(0, -0.45, 0);
      hip.add(knee);
      part(new THREE.BoxGeometry(0.15, 0.44, 0.17), armor, 0, -0.22, 0, knee, 'body');
      part(new THREE.BoxGeometry(0.19, 0.1, 0.28), plate, 0, -0.45, -0.05, knee, 'body');
      // glowing knee / shin accents
      part(new THREE.BoxGeometry(0.02, 0.18, 0.02), glow, s * 0.075, -0.22, -0.085, knee, null);
      this.legs.push({ hip, knee, s });
    }

    // pelvis + torso
    part(new THREE.BoxGeometry(0.44, 0.2, 0.28), plate, 0, 1.02, 0, this.group, 'body');
    this.torso = new THREE.Group();
    this.torso.position.y = 1.32;
    this.group.add(this.torso);
    part(new THREE.BoxGeometry(0.52, 0.48, 0.28), armor, 0, 0, 0, this.torso, 'body');
    part(new THREE.BoxGeometry(0.4, 0.3, 0.06), plate, 0, 0.03, -0.16, this.torso, 'body');
    // glowing core
    part(new THREE.BoxGeometry(0.09, 0.09, 0.03), glow, 0, 0.08, -0.2, this.torso, null);
    // backpack
    part(new THREE.BoxGeometry(0.34, 0.32, 0.14), plate, 0, 0.02, 0.2, this.torso, null);
    part(new THREE.BoxGeometry(0.2, 0.02, 0.02), glow, 0, 0.14, 0.27, this.torso, null);

    // shoulders
    for (const s of [-1, 1]) {
      part(new THREE.BoxGeometry(0.18, 0.16, 0.24), armor, s * 0.34, 1.55, 0, this.group, 'body');
    }

    // arms
    this.arms = [];
    for (const s of [-1, 1]) {
      const shoulder = new THREE.Group();
      shoulder.position.set(s * 0.34, 1.5, 0);
      this.group.add(shoulder);
      part(new THREE.BoxGeometry(0.12, 0.32, 0.13), plate, 0, -0.18, 0, shoulder, 'body');
      const elbow = new THREE.Group();
      elbow.position.set(0, -0.34, 0);
      shoulder.add(elbow);
      part(new THREE.BoxGeometry(0.105, 0.3, 0.12), armor, 0, -0.15, 0, elbow, 'body');
      this.arms.push({ shoulder, elbow, s });
    }

    // head
    this.head = new THREE.Group();
    this.head.position.y = 1.75;
    this.group.add(this.head);
    part(new THREE.BoxGeometry(0.3, 0.24, 0.28), armor, 0, 0, 0, this.head, 'head');
    part(new THREE.BoxGeometry(0.34, 0.06, 0.3), plate, 0, 0.13, 0, this.head, 'head');
    const visor = part(new THREE.BoxGeometry(0.24, 0.06, 0.02), eye, 0, 0.01, -0.145, this.head, null);
    visor.castShadow = false;
    part(new THREE.BoxGeometry(0.03, 0.2, 0.24), trim, 0.16, 0, 0.02, this.head, null);
    part(new THREE.BoxGeometry(0.03, 0.2, 0.24), trim, -0.16, 0, 0.02, this.head, null);

    // weapon held at right side
    const gun = new THREE.Group();
    gun.position.set(0.3, 1.2, -0.2);
    this.group.add(gun);
    const gm = (w, h, d, x, y, z) => {
      const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), gunMat);
      m.position.set(x, y, z);
      m.castShadow = true;
      gun.add(m);
      return m;
    };
    gm(0.07, 0.09, 0.46, 0, 0, -0.12);
    gm(0.045, 0.045, 0.34, 0, 0.01, -0.46);
    gm(0.055, 0.14, 0.09, 0, -0.12, -0.02);
    gm(0.03, 0.05, 0.07, 0, 0.02, 0.12);
    const muzzleTip = new THREE.Object3D();
    muzzleTip.position.set(0, 0.01, -0.64);
    gun.add(muzzleTip);
    this.muzzle = muzzleTip;
    this.gun = gun;

    // right hand on gun
    part(new THREE.BoxGeometry(0.08, 0.08, 0.09), plate, 0.3, 1.15, -0.12, this.group, null);

    // scale hp by wave visually via core
    glow.emissiveIntensity = 1.8 + wave * 0.2;
  }

  takeDamage(amount, head = false) {
    if (this.dead) return false;
    this.hp -= amount;
    this.hitFlash = 0.14;
    for (const m of this.mats) {
      m.emissive.setHex(0xff8a3c);
      m.emissiveIntensity = m === this.mats[3] ? 6 : 1.2;
    }
    if (this.hp <= 0) {
      this.die(head);
      return true;
    }
    return false;
  }

  die(head) {
    this.dead = true;
    this.deathT = 0;
    this.burst = 0;
    const p = this.group.position.clone();
    p.y = 1.2;
    this.fx.burst(p, new THREE.Vector3(0, 1, 0.3).normalize(), 0xff7a20, 34, 9, 0.22);
    this.fx.burst(p, new THREE.Vector3(0, 1, 0.3).normalize(), 0x7fe7ff, 14, 5, 0.12);
    this.audio.enemyDeath();
    this.manager.onEnemyDeath(this, head);
  }

  shoot(dist) {
    const from = new THREE.Vector3();
    this.muzzle.getWorldPosition(from);
    const eye = this.player.camera.getWorldPosition(new THREE.Vector3());
    const accuracy = Math.min(0.72, 0.4 + this.manager.wave * 0.025);
    const hitChance = accuracy * (dist < 12 ? 1 : dist < 22 ? 0.8 : 0.55);
    const willHit = Math.random() < hitChance;
    const target = eye.clone();
    if (!willHit) {
      target.x += (Math.random() - 0.5) * 2.4;
      target.y += (Math.random() - 0.6) * 1.6;
      target.z += (Math.random() - 0.5) * 2.4;
    } else {
      target.x += (Math.random() - 0.5) * 0.25;
      target.y += (Math.random() - 0.5) * 0.25;
    }
    this.fx.tracer(from, target, 0xffb060, 0.85);
    this.fx.burst(from, new THREE.Vector3(0, 0.2, -1), 0xffc070, 4, 2.5, 0.08);
    this.audio.enemyShot();
    if (willHit && this.player.alive) {
      this.player.damage(5 + Math.random() * 4);
    }
  }

  update(dt, t, others) {
    if (this.dead) {
      this.deathT += dt;
      if (this.deathT > 0.15) {
        const k = Math.min(1, (this.deathT - 0.15) / 0.55);
        const ease = 1 - Math.pow(1 - k, 3);
        this.group.rotation.x = ease * (Math.PI / 2 - 0.1);
        this.group.position.y = -Math.sin(ease * Math.PI) * 0.08;
      }
      if (this.deathT > 2.6) {
        this.group.position.y -= dt * 0.5;
      }
      if (this.deathT > 3.2) {
        this.group.scale.multiplyScalar(Math.max(0, 1 - dt * 1.5));
      }
      return;
    }

    // hit flash decay
    if (this.hitFlash > 0) {
      this.hitFlash -= dt;
      if (this.hitFlash <= 0) {
        this.mats[0].emissive.setHex(0x000000);
        this.mats[0].emissiveIntensity = 0;
        this.mats[1].emissive.setHex(0x000000);
        this.mats[1].emissiveIntensity = 0;
        this.mats[2].emissive.setHex(0x000000);
        this.mats[2].emissiveIntensity = 0;
        this.mats[3].emissive.setHex(0xff5a16);
        this.mats[3].emissiveIntensity = 2.4;
      }
    }

    // spawn materialize
    if (this.state === 'spawn') {
      this.spawnT += dt;
      const k = Math.min(1, this.spawnT / 0.55);
      const ease = 1 - Math.pow(1 - k, 3);
      this.group.scale.set(1, Math.max(0.02, ease), 1);
      if (this.spawnT < 0.1) {
        this.fx.burst(this.group.position.clone().setY(0.2), new THREE.Vector3(0, 1, 0), 0x7fe7ff, 12, 3, 0.1);
      }
      if (k >= 1) this.state = 'active';
      return;
    }

    const playerPos = this.player.pos;
    const to = new THREE.Vector3(playerPos.x - this.group.position.x, 0, playerPos.z - this.group.position.z);
    const dist = to.length();
    if (dist > 0.001) to.multiplyScalar(1 / dist);

    // line of sight
    this.losT -= dt;
    if (this.losT <= 0) {
      this.losT = 0.14 + Math.random() * 0.08;
      const eyePos = this.group.position.clone().setY(1.65);
      const pEye = this.player.camera.getWorldPosition(new THREE.Vector3());
      this.los = this.player.alive && !lineBlocked(eyePos, pEye, this.world.raycastMeshes);
    }

    // movement
    let move = new THREE.Vector3();
    if (dist > 15) {
      move.copy(to);
    } else if (dist < 6.5) {
      move.copy(to).multiplyScalar(-0.8);
    } else {
      this.strafeT -= dt;
      if (this.strafeT <= 0) {
        this.strafeT = 1.6 + Math.random() * 1.8;
        this.strafeDir *= -1;
      }
      move.set(-to.z * this.strafeDir, 0, to.x * this.strafeDir);
    }

    // separation from other enemies
    for (const o of others) {
      if (o === this || o.dead) continue;
      const dx = this.group.position.x - o.group.position.x;
      const dz = this.group.position.z - o.group.position.z;
      const d = Math.hypot(dx, dz);
      if (d < 1.3 && d > 0.001) {
        move.x += (dx / d) * (1.3 - d) * 1.6;
        move.z += (dz / d) * (1.3 - d) * 1.6;
      }
    }

    if (move.lengthSq() > 0.0001) move.normalize();
    const step = this.speed * dt;
    this.group.position.x += move.x * step;
    this.group.position.z += move.z * step;
    resolveCircle(this.group.position, 0.45, this.world.colliders, 1.9);
    this.group.position.x = Math.max(-32, Math.min(32, this.group.position.x));
    this.group.position.z = Math.max(-32, Math.min(32, this.group.position.z));

    // facing
    const targetYaw = Math.atan2(-to.x, -to.z);
    let dy = targetYaw - this.group.rotation.y;
    while (dy > Math.PI) dy -= Math.PI * 2;
    while (dy < -Math.PI) dy += Math.PI * 2;
    this.group.rotation.y += dy * Math.min(1, dt * 7);

    // walk animation
    this.walkPhase += dt * (2.5 + this.speed * 1.6);
    const swing = Math.sin(this.walkPhase) * 0.5;
    if (this.legs) {
      this.legs[0].hip.rotation.x = swing;
      this.legs[1].hip.rotation.x = -swing;
      this.legs[0].knee.rotation.x = Math.max(0, -Math.sin(this.walkPhase)) * 0.5;
      this.legs[1].knee.rotation.x = Math.max(0, Math.sin(this.walkPhase)) * 0.5;
    }
    if (this.arms) {
      this.arms[0].shoulder.rotation.x = -swing * 0.5;
      this.arms[1].shoulder.rotation.x = -1.15;
      this.arms[1].elbow.rotation.x = -0.3;
    }
    this.torso.position.y = 1.32 + Math.sin(this.walkPhase * 2) * 0.012;

    // shooting
    this.nextShot -= dt;
    if (this.burst > 0) {
      this.burstT -= dt;
      if (this.burstT <= 0) {
        this.burstT = 0.13;
        this.burst--;
        this.shoot(dist);
        if (this.burst === 0) this.nextShot = 1.4 + Math.random() * 1.6;
      }
    } else if (this.los && dist < 30 && this.nextShot <= 0 && this.player.alive) {
      this.burst = 3;
      this.burstT = 0;
    }

    // idle visor pulse
    this.mats[3].emissiveIntensity = 2.2 + Math.sin(t * 3 + this.walkPhase) * 0.5;
  }

  dispose() {
    this.scene.remove(this.group);
    this.group.traverse((o) => {
      if (o.isMesh) {
        o.geometry.dispose();
        if (Array.isArray(o.material)) o.material.forEach((m) => m.dispose());
        else o.material.dispose();
      }
    });
    this.hitMeshes = [];
  }
}

export class EnemyManager {
  constructor(scene, world, fx, audio, player, hud, callbacks = {}) {
    this.scene = scene;
    this.world = world;
    this.fx = fx;
    this.audio = audio;
    this.player = player;
    this.hud = hud;
    this.onKill = callbacks.onKill || (() => {});
    this.onAllDead = callbacks.onAllDead || (() => {});
    this.enemies = [];
    this.hitMeshes = [];
    this.wave = 1;
    this.pending = 0;
    this.time = 0;
  }

  reset() {
    for (const e of this.enemies) e.dispose();
    this.enemies = [];
    this.hitMeshes = [];
    this.pending = 0;
  }

  spawnWave(wave, count) {
    this.wave = wave;
    this.pending = count;
    const used = new Set();
    for (let i = 0; i < count; i++) {
      let pos = null;
      let best = null;
      for (let attempt = 0; attempt < 12; attempt++) {
        const p = this.world.spawnPoints[Math.floor(Math.random() * this.world.spawnPoints.length)];
        const key = `${p.x},${p.z}`;
        if (used.has(key)) continue;
        const d = Math.hypot(p.x - this.player.pos.x, p.z - this.player.pos.z);
        if (d < 12) continue;
        best = p;
        used.add(key);
        break;
      }
      if (!best) {
        const p = this.world.spawnPoints[Math.floor(Math.random() * this.world.spawnPoints.length)];
        pos = new THREE.Vector3(p.x + (Math.random() - 0.5) * 4, 0, p.z + (Math.random() - 0.5) * 4);
      } else {
        pos = new THREE.Vector3(best.x, 0, best.z);
      }
      this.spawnEnemy(pos, wave);
    }
  }

  spawnEnemy(pos, wave) {
    const e = new Enemy(this, pos, wave);
    this.enemies.push(e);
    this.hitMeshes.push(...e.hitMeshes);
  }

  onEnemyDeath(enemy, head) {
    const idx = this.hitMeshes.findIndex((m) => m.userData.enemy === enemy);
    if (idx >= 0) this.hitMeshes = this.hitMeshes.filter((m) => m.userData.enemy !== enemy);
    this.onKill(enemy, head);
  }

  aliveCount() {
    return this.enemies.filter((e) => !e.dead).length;
  }

  remaining() {
    return this.aliveCount() + this.pending;
  }

  update(dt, t) {
    this.time = t;
    for (const e of this.enemies) e.update(dt, t, this.enemies);

    let removed = false;
    for (const e of this.enemies) {
      if (e.dead && e.deathT > 4.4) {
        e.dispose();
        removed = true;
      }
    }
    if (removed) this.enemies = this.enemies.filter((e) => e.deathT <= 4.4);
  }
}

