    keys.KeyW = forward > 0.1;
    keys.KeyS = forward < -0.1;
    keys.KeyA = strafe < -0.1;
    keys.KeyD = strafe > 0.1;

    const magnitude = Math.hypot(x, y);
    this.sprinting = magnitude > 0.3 && !this.adsing;
  }

